const TaxCenterView = ({ employees, csgNominaData, adminPayrollHistory, nominaDetailData, onOpenPayrollAdvice }) => {
    const [fiscalYear, setFiscalYear] = useState(() => {
        const curYear = new Date().getFullYear();
        return curYear >= 2026 ? curYear : 2026;
    });
    const [searchTerm, setSearchTerm] = useState('');

    const availableYears = useMemo(() => {
        const yearsSet = new Set();
        yearsSet.add(2026); // Garantizar que 2026 siempre esté presente por defecto

        const getYear = (periodStr) => {
            if (!periodStr) return null;
            const parts = periodStr.split(/[—–-]/);
            if (parts.length < 2) return null;
            const endPart = parts[parts.length - 1].trim();
            const yearMatch = endPart.match(/\/(\d{4})$/);
            return yearMatch ? parseInt(yearMatch[1]) : null;
        };

        if (nominaDetailData && Array.isArray(nominaDetailData)) {
            nominaDetailData.forEach(r => {
                const y = getYear(r.periodo || r.Periodo);
                if (y && y >= 2026) yearsSet.add(y);
            });
        }
        if (csgNominaData && Array.isArray(csgNominaData)) {
            csgNominaData.forEach(r => {
                const y = getYear(r.periodo);
                if (y && y >= 2026) yearsSet.add(y);
            });
        }
        if (adminPayrollHistory && Array.isArray(adminPayrollHistory)) {
            adminPayrollHistory.forEach(r => {
                const y = getYear(r.periodo);
                if (y && y >= 2026) yearsSet.add(y);
            });
        }

        return Array.from(yearsSet).sort((a, b) => b - a);
    }, [nominaDetailData, csgNominaData, adminPayrollHistory]);

    // --- LÓGICA DE AGREGACIÓN FISCAL ---
    const reportData = useMemo(() => {
        const data = {};
        const periodsFound = new Set();
        const periodBounds = []; // Almacenará objetos { key: string, start: Date, end: Date } para mapeo dinámico

        // 0. Crear mapas de búsqueda maestros desde la lista de personal (employees)
        const nameToIdMap = {};
        const idToInfoMap = {};

        employees.forEach(emp => {
            if (!emp) return;
            const normalized = normalizeName(emp.nombre);
            const id = String(emp.codigo_empleado || '').trim();
            if (id) {
                idToInfoMap[id] = {
                    nombre: emp.nombre,
                    cargo: emp.cargo || 'Personal',
                    firstName: emp.first_name,
                    lastName: emp.last_name
                };
                if (normalized) nameToIdMap[normalized] = id;
            }
        });

        // Helper para resolver ID a partir de Nombre o ID parcial
        const resolveEmployeeId = (originalName, originalId) => {
            const cleanId = String(originalId || '').trim();
            const normName = normalizeName(originalName);

            // Preferencia 1: ID directo si existe en el mapa maestro
            if (cleanId && idToInfoMap[cleanId]) return cleanId;

            // Preferencia 2: Búsqueda por nombre normalizado en el mapa maestro
            if (normName && nameToIdMap[normName]) return nameToIdMap[normName];

            // Preferencia 3: Si no hay ID pero hay nombre, devolver ID parcial o el nombre mismo si no hay nada más
            return cleanId || originalName || 'S/ID';
        };

        // Helper para extraer el año a partir de un periodo del formato "MM/DD/YYYY - MM/DD/YYYY"
        const getYearFromPeriod = (periodStr) => {
            if (!periodStr) return null;
            const parts = periodStr.split(/[—–-]/);
            if (parts.length < 2) return null;
            const endPart = parts[parts.length - 1].trim();
            const yearMatch = endPart.match(/\/(\d{4})$/);
            return yearMatch ? parseInt(yearMatch[1]) : null;
        };

        // Helper para parsear fechas de periodos "MM/DD/YYYY"
        const parseDate = (dateStr) => {
            if (!dateStr) return null;
            const parts = dateStr.split('/');
            if (parts.length === 3) {
                return new Date(parseInt(parts[2]), parseInt(parts[0]) - 1, parseInt(parts[1]));
            }
            return new Date(dateStr);
        };

        // A. Registrar periodos bisemanales de KBS (nominaDetailData)
        if (nominaDetailData && Array.isArray(nominaDetailData)) {
            nominaDetailData.forEach(record => {
                try {
                    if (!record || !(record.Periodo || record.periodo) || !(record.Data_JSON || record.data_json)) return;
                    const year = getYearFromPeriod(record.Periodo || record.periodo);
                    if (year !== fiscalYear) return;

                    const periodKey = (record.Periodo || record.periodo).trim();
                    periodsFound.add(periodKey);

                    // Parsear límites de la bisemana
                    const parts = periodKey.split(/[—–-]/);
                    if (parts.length >= 2) {
                        const startD = parseDate(parts[0].trim());
                        const endD = parseDate(parts[1].trim());
                        if (startD && endD && !periodBounds.some(b => b.key === periodKey)) {
                            periodBounds.push({ key: periodKey, start: startD, end: endD });
                        }
                    }

                    // Procesar a TODOS los empleados en la nómina (KBS)
                    const payload = typeof (record.Data_JSON || record.data_json) === 'string' ? JSON.parse(record.Data_JSON || record.data_json) : (record.Data_JSON || record.data_json);
                    const rowsList = Array.isArray(payload) ? payload : [];

                    rowsList.forEach(empRow => {
                        if (!empRow) return;
                        const originalName = empRow.empleado || empRow.nombre;
                        const originalId = empRow.id || empRow.codigo;
                        if (!originalName) return;

                        const empId = resolveEmployeeId(originalName, originalId);
                        const info = idToInfoMap[empId] || { nombre: originalName, cargo: empRow.cargo || 'Personal' };

                        if (!data[empId]) {
                           data[empId] = {
                               id: empId,
                               nombre: info.nombre,
                               cargo: info.cargo,
                               firstName: info.firstName,
                               lastName: info.lastName,
                               totalBox1: 0,
                               periods: {}
                           };
                        }
                        const amount = parseFloat(empRow.total_lgm) || parseFloat(empRow.total) || 0;
                        data[empId].periods[periodKey] = (data[empId].periods[periodKey] || 0) + amount;
                        data[empId].totalBox1 += amount;
                    });
                } catch (e) {
                    console.error("Error processing KBS payroll in Nomina_Detalle for 1099:", e);
                }
            });
        }

        // B. Registrar periodos bisemanales de CSG (csgNominaData)
        if (csgNominaData && Array.isArray(csgNominaData)) {
            csgNominaData.forEach(record => {
                try {
                    if (!record || !record.periodo || !record.servicios_json) return;
                    const year = getYearFromPeriod(record.periodo);
                    if (year !== fiscalYear) return;

                    const periodKey = record.periodo.trim();
                    periodsFound.add(periodKey);

                    // Parsear límites de la bisemana
                    const parts = periodKey.split(/[—–-]/);
                    if (parts.length >= 2) {
                        const startD = parseDate(parts[0].trim());
                        const endD = parseDate(parts[1].trim());
                        if (startD && endD && !periodBounds.some(b => b.key === periodKey)) {
                            periodBounds.push({ key: periodKey, start: startD, end: endD });
                        }
                    }

                    // Procesar a TODOS los empleados en la nómina (CSG)
                    const payload = typeof record.servicios_json === 'string' ? JSON.parse(record.servicios_json) : record.servicios_json;
                    const rowsList = Array.isArray(payload) ? payload : [];

                    rowsList.forEach(svc => {
                        if (!svc) return;
                        const originalName = svc.empleado;
                        const originalId = svc.codigo_empleado;
                        if (!originalName) return;

                        const empId = resolveEmployeeId(originalName, originalId);
                        const info = idToInfoMap[empId] || { nombre: originalName, cargo: svc.cargo || 'Cleaning' };

                        if (!data[empId]) {
                            data[empId] = {
                                id: empId,
                                nombre: info.nombre,
                                cargo: info.cargo,
                                firstName: info.firstName,
                                lastName: info.lastName,
                                totalBox1: 0,
                                periods: {}
                            };
                        }
                        const amount = parseFloat(svc.monto_lgm) || 0;
                        data[empId].periods[periodKey] = (data[empId].periods[periodKey] || 0) + amount;
                        data[empId].totalBox1 += amount;
                    });
                } catch (e) {
                    console.error("Error processing CSG payroll in CSG_Nomina for 1099:", e);
                }
            });
        }

        // Helper para encontrar la bisemana correspondiente para un pago (administrativos)
        const findMatchingPeriod = (endDateStr) => {
            const targetDate = parseDate(endDateStr);
            if (!targetDate) return null;

            // 1. Buscar coincidencia exacta o contenedor
            let bestPeriod = null;
            for (const bound of periodBounds) {
                if (targetDate >= bound.start && targetDate <= bound.end) {
                    return bound.key;
                }
            }

            // 2. Si no contiene la fecha, buscar la bisemana más cercana en días
            let minDiff = Infinity;
            for (const bound of periodBounds) {
                const diffEnd = Math.abs(targetDate - bound.end);
                if (diffEnd < minDiff) {
                    minDiff = diffEnd;
                    bestPeriod = bound.key;
                }
            }
            return bestPeriod;
        };

        // C. Consolidar Personal Administrativo (adminPayrollHistory)
        if (adminPayrollHistory && Array.isArray(adminPayrollHistory)) {
            adminPayrollHistory.forEach(history => {
                try {
                    if (!history || !history.periodo || !history.empleados) return;

                    // Extraer la fecha final del periodo (ej: "02/22/2026 — 03/07/2026")
                    const dateParts = history.periodo.split(/[—–-]/);
                    if (dateParts.length < 2) return;

                    const endDateStr = dateParts[dateParts.length - 1].trim();
                    const year = getYearFromPeriod(history.periodo);
                    if (year !== fiscalYear) return;

                    // Buscar la bisemana correspondiente registrada
                    const periodKey = findMatchingPeriod(endDateStr);
                    if (!periodKey) return; // Si no hay bisemanas en ese año, omitir

                    const payload = history.empleados || [];

                    payload.forEach(empRow => {
                        if (!empRow) return;
                        const originalName = empRow.nombre;
                        const originalId = empRow.codigo_empleado;
                        if (!originalName) return;

                        const empId = resolveEmployeeId(originalName, originalId);
                        const info = idToInfoMap[empId] || { nombre: originalName, cargo: empRow.cargo || 'Administrativo' };

                        if (!data[empId]) {
                            data[empId] = {
                                id: empId,
                                nombre: info.nombre,
                                cargo: info.cargo,
                                firstName: info.firstName,
                                lastName: info.lastName,
                                totalBox1: 0,
                                periods: {}
                            };
                        }
                        const amount = parseFloat(empRow.total) || 0;
                        data[empId].periods[periodKey] = (data[empId].periods[periodKey] || 0) + amount;
                        data[empId].totalBox1 += amount;
                    });
                } catch (e) {
                    console.error("Error processing admin payroll for 1099:", e);
                }
            });
        }

        // D. Ordenar columnas de periodos por fecha
        const sortedPeriods = Array.from(periodsFound).sort((a, b) => {
            const dateA = new Date(a.split(/[—–-]/)[0].trim());
            const dateB = new Date(b.split(/[—–-]/)[0].trim());
            return dateA - dateB;
        });

        return {
            rows: Object.values(data),
            periods: sortedPeriods
        };
    }, [fiscalYear, csgNominaData, adminPayrollHistory, nominaDetailData, employees]);

    const filteredRows = useMemo(() => {
        return reportData.rows
            .filter(row =>
                row.nombre.toLowerCase().includes(searchTerm.toLowerCase()) ||
                row.id.toString().includes(searchTerm)
            )
            .sort((a, b) => {
                const nameA = (a.lastName || a.nombre.split(' ').pop() || '').toLowerCase();
                const nameB = (b.lastName || b.nombre.split(' ').pop() || '').toLowerCase();
                return nameA.localeCompare(nameB);
            });
    }, [reportData.rows, searchTerm]);

    const handleExportExcel = () => {
        const exportData = filteredRows.map(row => {
            const dbEmp = employees.find(e => e.codigo_empleado === row.id) || {};

            const baseRow = {
                'Payer Type': dbEmp.payer_type || 'Individual',
                'Payer TIN Type': dbEmp.tin_type || 'SSN',
                'Payer TIN': dbEmp.tin ? `'${dbEmp.tin}` : '',
                'Bank Account': dbEmp.cuenta_bancaria ? `'${dbEmp.cuenta_bancaria}` : '',
                'P Business Name or Last Name': dbEmp.last_name || row.nombre.split(' ').pop(),
                'P First Name': dbEmp.first_name || row.nombre.split(' ')[0],
                'P Address 1': dbEmp.address_1 || '',
                'P City': dbEmp.city || '',
                'P State': dbEmp.state || '',
                'P ZIP or Foreign Postal Code': dbEmp.zip ? `'${dbEmp.zip}` : '',
                'P Country': dbEmp.country || 'EE. UU.',
                'P Email Address (optional)': dbEmp.email_tax || '',
                'Tienda': dbEmp.tienda || '',
                'Site Code': dbEmp.site_code ? `'${dbEmp.site_code}` : '',
                'Activo': dbEmp.fecha_egreso ? 'Inactivo' : 'Activo',
                'Box 1 Nonemployee Compensation': row.totalBox1,
            };

            // Añadir columnas de periodos
            reportData.periods.forEach(p => {
                baseRow[p] = row.periods[p] || 0;
            });

            return baseRow;
        });

        const ws = XLSX.utils.json_to_sheet(exportData);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, "Reporte 1099");
        XLSX.writeFile(wb, `Reporte_1099_${fiscalYear}_LogicPay.xlsx`);
    };

    return (
        <div className="space-y-8 animate-in fade-in duration-500">
            {/* Header / Filtros - Estilo Personal */}
            <div className="flex flex-col md:flex-row gap-4 mb-10 items-stretch animate-in fade-in slide-in-from-bottom-4 duration-500">
                <div className="relative flex-1 group h-11">
                    <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-300 group-focus-within:text-[#303a7f] transition-colors" size={20} />
                    <input
                        type="text"
                        placeholder="Filtrar por nombre o apellido..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="w-full h-full bg-white border-2 border-brand-primary/20 text-[#333333] rounded-2xl pl-14 pr-6 outline-none focus:border-[#303a7f]/20 focus:ring-4 focus:ring-[#303a7f]/5 transition-all font-bold shadow-sm text-sm placeholder:text-gray-300"
                    />
                </div>

                <div className="h-11 bg-white border-2 border-brand-primary/10 rounded-2xl p-1 flex items-center shadow-sm">
                    <select
                        value={fiscalYear}
                        onChange={(e) => setFiscalYear(parseInt(e.target.value))}
                        className="h-full bg-white border-none rounded-xl px-4 text-[10px] font-black text-[#303a7f] uppercase tracking-widest outline-none cursor-pointer hover:bg-gray-50 transition-colors"
                    >
                        {availableYears.map(year => (
                            <option key={year} value={year}>Fiscal {year}</option>
                        ))}
                    </select>
                </div>

                <div className="flex gap-2 h-11">
                    <button
                        onClick={onOpenPayrollAdvice}
                        style={{ backgroundColor: '#303a7f' }}
                        className="h-full text-white font-black px-8 rounded-2xl transition-all flex items-center justify-center gap-3 shadow-2xl shadow-blue-900/20 active:scale-95 group overflow-hidden relative hover:bg-[#252a5e] whitespace-nowrap"
                    >
                        <div className="absolute inset-0 bg-white/10 -translate-x-full group-hover:translate-x-full transition-transform duration-700 pointer-events-none" />
                        <Mail size={16} className="group-hover:scale-110 transition-transform duration-500" />
                        <span className="tracking-widest uppercase text-[10px]">Payroll Advice</span>
                    </button>

                    <button
                        onClick={handleExportExcel}
                        style={{ backgroundColor: '#6bbdb7' }}
                        className="h-full text-white font-black px-8 rounded-2xl transition-all flex items-center justify-center gap-3 shadow-2xl shadow-teal-900/20 active:scale-95 group overflow-hidden relative hover:bg-[#59aba5] whitespace-nowrap"
                    >
                        <div className="absolute inset-0 bg-white/10 -translate-x-full group-hover:translate-x-full transition-transform duration-700 pointer-events-none" />
                        <Download size={16} className="group-hover:scale-110 transition-transform duration-500" />
                        <span className="tracking-widest uppercase text-[10px]">Exportar Excel</span>
                    </button>
                </div>
            </div>

            {/* Tabla de Reporte */}
            <div className="bg-white rounded-[3rem] shadow-2xl shadow-blue-900/5 border-2 border-brand-primary/5 overflow-hidden">
                <div className="overflow-x-auto custom-scrollbar">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="bg-gray-50/80">
                                <th className="p-6 text-[10px] font-black text-[#303a7f] uppercase tracking-widest sticky left-0 bg-gray-50/80 z-10 border-b-2 border-gray-100">Personal / ID</th>
                                <th className="p-6 text-[10px] font-black text-gray-400 uppercase tracking-widest text-center border-b-2 border-gray-100">TIN (Tax ID)</th>
                                <th className="p-6 text-[10px] font-black text-[#6bbdb7] uppercase tracking-widest text-right border-b-2 border-gray-100 bg-[#6bbdb7]/5">Total Box 1</th>
                                {reportData.periods.map(p => {
                                    const parts = p.split(' - ');
                                    const start = parts[0] || '';
                                    const end = parts[1] || '';
                                    return (
                                        <th key={p} className="p-6 text-[9px] font-bold text-gray-400 uppercase tracking-tighter text-center border-b-2 border-gray-100 border-l-2 border-gray-50">
                                            {start.slice(0, 5)} {end ? `- ${end.slice(0, 5)}` : ''}
                                        </th>
                                    );
                                })}
                            </tr>
                        </thead>
                        <tbody className="divide-y-2 divide-gray-50">
                            {filteredRows.length === 0 ? (
                                <tr>
                                    <td colSpan={reportData.periods.length + 3} className="p-20 text-center text-gray-300 font-bold italic">
                                        No se encontraron registros para el año {fiscalYear}.
                                    </td>
                                </tr>
                            ) : (
                                filteredRows.map((row) => {
                                    const dbEmp = employees.find(e => e.codigo_empleado === row.id) || {};
                                    return (
                                        <tr key={row.id} className="hover:bg-blue-50/20 transition-colors group">
                                            <td className="p-6 sticky left-0 bg-white group-hover:bg-blue-50/20 z-10 border-r-2 border-gray-50 shadow-[4px_0_10px_-4px_rgba(0,0,0,0.05)]">
                                                <div className="flex flex-col">
                                                    <span className="text-sm font-black text-[#303a7f] uppercase tracking-tight">
                                                        {row.lastName && row.firstName ? `${row.lastName} ${row.firstName}` : row.nombre}
                                                    </span>
                                                    <span className="text-[9px] font-black text-[#6bbdb7] uppercase tracking-widest mt-0.5">ID: {row.id}</span>
                                                </div>
                                            </td>
                                            <td className="p-6 text-center">
                                                <span className="text-xs font-bold text-gray-500 tabular-nums">
                                                    {dbEmp.tin ? `***-**-${dbEmp.tin.slice(-4)}` : '--'}
                                                </span>
                                            </td>
                                            <td className="p-6 text-right bg-[#6bbdb7]/5">
                                                <span className="text-sm font-black text-[#303a7f] tabular-nums">
                                                    ${row.totalBox1.toLocaleString('en-US', { minimumFractionDigits: 2 })}
                                                </span>
                                            </td>
                                            {reportData.periods.map(p => (
                                                <td key={p} className="p-6 text-center border-l-2 border-gray-50">
                                                    <span className={`text-xs font-bold tabular-nums ${row.periods[p] ? 'text-gray-600' : 'text-gray-200'}`}>
                                                        {row.periods[p] ? `$${row.periods[p].toLocaleString('en-US', { minimumFractionDigits: 2 })}` : '$0.00'}
                                                    </span>
                                                </td>
                                            ))}
                                        </tr>
                                    );
                                })
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

const PayrollAdvicesGlobalView = ({ isOpen, onClose, nominaHistoryData, nominaDetailData, csgNominaData, employees, stores, specialProjectsData, adminPayrollHistory, adminEmployees, paEmailsSent, onEmailSent }) => {
    const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());
    const [selectedPeriod, setSelectedPeriod] = useState(null);
    const [biweeklyEmployees, setBiweeklyEmployees] = useState([]);
    const [isSending, setIsSending] = useState(false);
    const [sendingProgress, setSendingProgress] = useState({ current: 0, total: 0, status: 'idle', logs: [] });
    const [sentPayStubs, setSentPayStubs] = useState({});
    const [previewPdf, setPreviewPdf] = useState({ isOpen: false, url: '', name: '' });
    const [searchTerm, setSearchTerm] = useState('');
    const [notificationModal, setNotificationModal] = useState({ isOpen: false, type: 'loading', message: '' });

    // --- Helper: Generar Periodos (Reutilizado) ---
    const generateBiweeklyPeriods = useCallback(() => {
        const weeks = [];
        let current = new Date(2026, 0, 1);
        while (current.getDay() !== 0) current.setDate(current.getDate() - 1);
        const endTarget = new Date(2040, 11, 31);
        const yearWeekCounts = {};
        while (current <= endTarget) {
            const start = new Date(current);
            const end = new Date(current);
            end.setDate(end.getDate() + 6);
            const saturdayYear = end.getFullYear();
            if (!yearWeekCounts[saturdayYear]) yearWeekCounts[saturdayYear] = 0;
            yearWeekCounts[saturdayYear]++;
            weeks.push({
                start: start.toLocaleDateString('en-US', { month: '2-digit', day: '2-digit', year: 'numeric' }),
                end: end.toLocaleDateString('en-US', { month: '2-digit', day: '2-digit', year: 'numeric' }),
                weekNumInYear: yearWeekCounts[saturdayYear],
                weekYear: saturdayYear
            });
            current.setDate(current.getDate() + 7);
        }
        const biweekly = [];
        for (let i = 0; i < weeks.length; i += 2) {
            const w1 = weeks[i];
            const w2 = weeks[i + 1];
            biweekly.push({
                range: `${w1.start} - ${w2.end}`,
                w1, w2,
                filterYear: w1.weekYear,
                label: w1.weekYear === w2.weekYear ? `Semanas ${w1.weekNumInYear} y ${w2.weekNumInYear}` : `S. ${w1.weekNumInYear} (${w1.weekYear}) y S. ${w2.weekNumInYear} (${w2.weekYear})`
            });
        }
        return biweekly;
    }, []);

    const allPeriods = useMemo(() => generateBiweeklyPeriods(), [generateBiweeklyPeriods]);
    const filteredPeriods = useMemo(() => allPeriods.filter(p => p.filterYear === selectedYear), [allPeriods, selectedYear]);

    // --- Efecto: Seleccionar último periodo procesado al abrir ---
    useEffect(() => {
        if (isOpen && nominaHistoryData.length > 0 && !selectedPeriod) {
            const sortedHistory = [...nominaHistoryData].sort((a, b) => {
                const dateA = new Date(a.fecha_inicio);
                const dateB = new Date(b.fecha_inicio);
                return dateB - dateA;
            });
            const latest = sortedHistory[0];
            const latestPeriod = allPeriods.find(p => normalizeDate(p.w1.start) === normalizeDate(latest.fecha_inicio));
            if (latestPeriod) {
                setSelectedPeriod(latestPeriod);
                setSelectedYear(latestPeriod.filterYear);
            }
        }
    }, [isOpen, nominaHistoryData, allPeriods, selectedPeriod]);

    // --- Lógica de Consolidación Global (Usando Nomina_Detalle + CSG_Nomina) ---
    useEffect(() => {
        if (!selectedPeriod || (!nominaDetailData.length && !csgNominaData.length)) return;

        const empMap = {};

        // Filtrar registros que coincidan con el periodo seleccionado
        const periodRecords = nominaDetailData.filter(record => {
            const periodVal = String(record.periodo || record.Periodo || '').trim();
            return periodVal === String(selectedPeriod.range).trim();
        });

        periodRecords.forEach(record => {
            try {
                const dataJsonRaw = record.Data_JSON || record.data_json;
                if (!dataJsonRaw) return;

                // Si ya fue parseado como objeto por fetchNominaDetail, lo usamos, si no lo parseamos.
                let employeesList = [];
                if (typeof dataJsonRaw === 'string') {
                    employeesList = JSON.parse(dataJsonRaw);
                } else if (Array.isArray(dataJsonRaw)) {
                    employeesList = dataJsonRaw;
                }

                const storeName = record.tienda || record.Tienda || record.nombre;

                employeesList.forEach(emp => {
                    const nombreEmp = emp.empleado || emp.nombre;
                    const idEmp = emp.id || emp.codigo;
                    if (!nombreEmp) return;

                    const empId = `${String(nombreEmp).trim().toLowerCase()}_${String(idEmp).trim()}`;

                    if (!empMap[empId]) {
                        const dbEmp = employees.find(e =>
                            String(e.nombre).trim().toLowerCase() === String(nombreEmp).trim().toLowerCase() ||
                            String(e.codigo_empleado).trim() === String(idEmp).trim()
                        );
                        const fullAddress = dbEmp ? `${dbEmp.address_1}, ${dbEmp.city}, ${dbEmp.state} ${dbEmp.zip}` : '';
                        const rate = dbEmp ? Number(dbEmp.pay_rate || dbEmp.rate || 0) : 0;

                        empMap[empId] = {
                            id: empId,
                            nombre: nombreEmp,
                            semana1: 0,
                            semana2: 0,
                            pe: 0,
                            peEarnings: 0,
                            totalPay: 0,
                            rate: rate,
                            cargo: emp.cargo || (dbEmp ? dbEmp.cargo : 'Personal'),
                            address: fullAddress,
                            stores: new Set()
                        };
                    }

                    const entry = empMap[empId];
                    entry.semana1 += Number(emp.w1 || 0);
                    entry.semana2 += Number(emp.w2 || 0);
                    entry.pe += Number(emp.pe || 0);
                    entry.totalPay += Number(emp.total_lgm || 0);
                    entry.stores.add(storeName);

                    // Si el rate es 0, intentamos estimarlo del registro si total_hrs > 0
                    if (entry.rate === 0 && Number(emp.total_hrs) > 0) {
                        entry.rate = Number(emp.total_lgm) / Number(emp.total_hrs);
                    }
                });
            } catch (e) {
                console.error("Error procesando registro de Nomina_Detalle", e);
            }
        });

        // 2. Procesar registros de CSG_Nomina
        const periodCsgRecords = (csgNominaData || []).filter(record => {
            return String(record.periodo).trim() === String(selectedPeriod.range).trim();
        });

        periodCsgRecords.forEach(record => {
            try {
                const services = JSON.parse(record.servicios_json || '[]');
                services.forEach(svc => {
                    const nombreEmp = svc.empleado;
                    const idEmp = svc.codigo_empleado;
                    if (!nombreEmp) return;

                    const empId = `${String(nombreEmp).trim().toLowerCase()}_${String(idEmp).trim()}`;

                    if (!empMap[empId]) {
                        const dbEmp = employees.find(e =>
                            String(e.nombre).trim().toLowerCase() === String(nombreEmp).trim().toLowerCase() ||
                            String(e.codigo_empleado).trim() === String(idEmp).trim()
                        );
                        const fullAddress = dbEmp ? `${dbEmp.address_1}, ${dbEmp.city}, ${dbEmp.state} ${dbEmp.zip}` : '';
                        const rate = dbEmp ? Number(dbEmp.pay_rate || dbEmp.rate || 0) : 0;

                        empMap[empId] = {
                            id: empId,
                            nombre: nombreEmp,
                            semana1: 0,
                            semana2: 0,
                            pe: 0,
                            csgEarnings: 0,
                            totalPay: 0,
                            rate: rate,
                            cargo: svc.cargo || (dbEmp ? dbEmp.cargo : 'Cleaning Staff'),
                            address: fullAddress,
                            stores: new Set()
                        };
                    }

                    const entry = empMap[empId];
                    entry.totalPay += Number(svc.monto_lgm || 0);
                    entry.csgEarnings = (entry.csgEarnings || 0) + Number(svc.monto_lgm || 0);
                    entry.stores.add("CSG Cleaning");
                });
            } catch (e) {
                console.error("Error procesando registro de CSG_Nomina", e);
            }
        });

        const periodAdminRecords = (adminPayrollHistory || []).filter(record => {
            const normalize = (s) => String(s || '').replace(/[—–-]/g, '-').replace(/\s+/g, ' ').trim();
            return normalize(record.periodo) === normalize(selectedPeriod.range);
        });

        periodAdminRecords.forEach(record => {
            try {
                const employeesList = typeof record.empleados === 'string' ? JSON.parse(record.empleados) : (record.empleados || []);

                employeesList.forEach(emp => {
                    const nombreEmp = emp.nombre;
                    if (!nombreEmp) return;

                    // Buscar datos reales en adminEmployees para obtener el código de 4 dígitos
                    const adminMatch = adminEmployees?.find(ae =>
                        String(ae.nombre).trim().toLowerCase() === String(nombreEmp).trim().toLowerCase()
                    );
                    const realCode = adminMatch ? String(adminMatch.codigo_empleado).trim() : (emp.codigo_empleado || 'ADMIN');

                    const empId = `${String(nombreEmp).trim().toLowerCase()}_${realCode}`;

                    if (!empMap[empId]) {
                        empMap[empId] = {
                            id: empId,
                            nombre: nombreEmp,
                            semana1: 0,
                            semana2: 0,
                            pe: 0,
                            csgEarnings: 0,
                            adminEarnings: 0,
                            totalPay: 0,
                            rate: 0,
                            cargo: adminMatch ? adminMatch.cargo : (emp.cargo || 'Administrativo'),
                            address: adminMatch ? `${adminMatch.address_1}, ${adminMatch.city}, ${adminMatch.state} ${adminMatch.zip}` : '',
                            stores: new Set()
                        };
                    } else {
                        if (empMap[empId].adminEarnings === undefined) empMap[empId].adminEarnings = 0;
                    }

                    const entry = empMap[empId];
                    entry.totalPay += Number(emp.total || 0);
                    entry.adminEarnings += Number(emp.total || 0);
                    entry.stores.add("Administración LGM");
                });
            } catch (e) {
                console.error("Error procesando registro de Admin_Nomina_Historico", e);
            }
        });

        const consolidated = Object.values(empMap).map(emp => {
            // Resolver correo buscando en ambas bases
            let email = emp.email_tax;
            if (!email) {
                const dbEmp = employees.find(e => String(e.codigo_empleado).trim() === String(emp.id.split('_')[1]).trim() || String(e.nombre).trim().toLowerCase() === String(emp.id.split('_')[0]).trim().toLowerCase());
                const adminEmp = adminEmployees?.find(e => String(e.codigo_empleado).trim() === String(emp.id.split('_')[1]).trim() || String(e.nombre).trim().toLowerCase() === String(emp.id.split('_')[0]).trim().toLowerCase());
                email = dbEmp?.email_tax || dbEmp?.correo || adminEmp?.email || null;
            }

            return {
                ...emp,
                email_tax: email,
                stores: Array.from(emp.stores)
            };
        });

        consolidated.sort((a, b) => a.nombre.localeCompare(b.nombre));
        setBiweeklyEmployees(consolidated);
    }, [selectedPeriod, nominaDetailData, csgNominaData, employees, adminPayrollHistory, adminEmployees]);

    const filteredEmployees = useMemo(() => {
        return biweeklyEmployees.filter(emp =>
            emp.nombre.toLowerCase().includes(searchTerm.toLowerCase()) ||
            emp.id.toLowerCase().includes(searchTerm.toLowerCase())
        );
    }, [biweeklyEmployees, searchTerm]);

    const handleSendAll = async () => {
        const recipients = biweeklyEmployees.filter(emp => emp.email_tax);
        if (recipients.length === 0) return alert("No hay empleados con correo.");
        if (!confirm(`¿Enviar ${recipients.length} recibos?`)) return;

        setSendingProgress({ current: 0, total: recipients.length, status: 'sending', logs: ["🚀 Iniciando envío masivo...", `Periodo: ${selectedPeriod.range}`] });

        for (let i = 0; i < recipients.length; i++) {
            const emp = recipients[i];
            const email = emp.email_tax;
            setSendingProgress(prev => ({ ...prev, current: i + 1, logs: [`Generando recibo para ${emp.nombre}...`, ...prev.logs] }));
            try {
                const pdfResult = await generatePayStubPDF(emp.id);
                if (pdfResult?.error) throw new Error(pdfResult.error);
                await sendEmail('payroll', { to: email, subject: `Payment Advice - ${selectedPeriod.range}`, body: `Hi, ${emp.nombre.split(' ')[0]}\n\nPlease find attached your payment advice.\n\nBest regards,\nLogic Group Management`, attachments: [{ name: `Recibo_${emp.nombre.replace(/\s+/g, '_')}.pdf`, type: 'application/pdf', base64: pdfResult }] });
                fetch('/api/audit-log', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ userId: user?.id, userName: user?.nombre, accion: 'envió el correo de', entidad: 'Recibo de Nómina', entidadNombre: emp.nombre }) }).catch(() => {});
                setSendingProgress(prev => ({ ...prev, logs: [`✅ Enviado a ${email}`, ...prev.logs] }));

                if (onEmailSent) {
                    const persistentKey = `${selectedPeriod.range.replace(/\s+/g, '')}#${emp.id}`;
                    onEmailSent(persistentKey);
                }
            } catch (error) {
                setSendingProgress(prev => ({ ...prev, logs: [`❌ Error en ${emp.nombre}: ${error.message}`, ...prev.logs] }));
            }
            await new Promise(r => setTimeout(r, 600));
        }
        setSendingProgress(prev => ({ ...prev, status: 'finished', logs: ["✨ Finalizado.", ...prev.logs] }));
    };

    const handleSendIndividual = async (emp) => {
        const email = emp.email_tax;
        if (!email) return alert("Email no encontrado.");
        setNotificationModal({ isOpen: true, type: 'loading', message: `Enviando a ${emp.nombre}...` });
        try {
            const pdfBase64 = await generatePayStubPDF(emp.id);
            await sendEmail('payroll', { to: email, subject: `Payment Advice - ${selectedPeriod.range}`, body: `Hi, ${emp.nombre.split(' ')[0]}\n\nPlease find attached your payment advice.\n\nBest regards,\nLogic Group Management`, attachments: [{ name: `Recibo_${emp.nombre}.pdf`, type: 'application/pdf', base64: pdfBase64 }] });
            fetch('/api/audit-log', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ userId: user?.id, userName: user?.nombre, accion: 'envió el correo de', entidad: 'Recibo de Nómina', entidadNombre: emp.nombre }) }).catch(() => {});
            setSentPayStubs(prev => ({ ...prev, [emp.id]: true }));
            if (onEmailSent) {
                const persistentKey = `${selectedPeriod.range.replace(/\s+/g, '')}#${emp.id}`;
                onEmailSent(persistentKey);
            }
            setNotificationModal({ isOpen: true, type: 'success', message: `Enviado con éxito.` });
        } catch (error) {
            setNotificationModal({ isOpen: true, type: 'error', message: `Error: ${error.message}` });
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[500] bg-[#f9f9f9] flex flex-col animate-in fade-in duration-500 overflow-hidden">
            <header className="px-12 py-6 bg-white border-b-2 border-gray-100 flex items-center justify-between shadow-sm">
                <div className="flex items-center gap-6">
                    <div className="p-3 bg-[#303a7f] text-white rounded-xl shadow-xl shadow-blue-900/20"><Mail size={20} /></div>
                    <div className="flex flex-col">
                        <h2 className="text-lg font-black text-[#303a7f] tracking-tighter uppercase leading-none mb-1">Payroll Advices</h2>
                        <div className="flex items-center gap-2">
                            <div className="h-0.5 w-6 bg-[#6bbdb7] rounded-full" />
                            <span className="text-[#6bbdb7] font-black uppercase text-[10px] tracking-[0.2em]">Consolidado Global de Recibos</span>
                        </div>
                    </div>
                </div>
                <div className="flex items-center gap-4">
                    <div className="flex items-center gap-3 bg-gray-50 p-2 rounded-2xl border-2 border-gray-100">
                        <div className="flex items-center bg-white rounded-xl px-3 py-1.5 shadow-sm">
                            <button onClick={() => setSelectedYear(y => y - 1)} className="p-1 hover:text-[#303a7f] transition-colors"><ChevronLeft size={14} /></button>
                            <span className="px-4 text-xs font-black text-[#303a7f]">{selectedYear}</span>
                            <button onClick={() => setSelectedYear(y => y + 1)} className="p-1 hover:text-[#303a7f] transition-colors"><ChevronRight size={14} /></button>
                        </div>
                        <select value={selectedPeriod?.range || ''} onChange={(e) => setSelectedPeriod(allPeriods.find(p => p.range === e.target.value))} className="bg-white border-none text-[10px] font-black text-[#303a7f] uppercase outline-none py-2 px-4 rounded-xl cursor-pointer">
                            <option value="">Selecciona Periodo</option>
                            {filteredPeriods.map(p => <option key={p.range} value={p.range}>{p.label} ({p.range})</option>)}
                        </select>
                    </div>
                    <button onClick={onClose} className="p-3 btn-close-danger rounded-xl transition-all"><X size={24} /></button>
                </div>
            </header>
            <main className="flex-1 overflow-hidden flex flex-col bg-[#fcfdfe]">
                <div className="flex-1 flex flex-col overflow-hidden p-8">
                    <div className="mb-8 flex flex-col md:flex-row gap-4 items-center justify-between">
                        <div className="relative flex-1 max-w-md w-full">
                            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" size={18} />
                            <input type="text" placeholder="Buscar empleado..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-white border-2 border-gray-100 rounded-2xl py-3 pl-12 pr-6 text-sm font-bold outline-none shadow-sm" />
                        </div>
                        <div className="flex items-center gap-4">
                            <button onClick={handleSendAll} disabled={!selectedPeriod || biweeklyEmployees.length === 0} className="px-8 py-3 bg-[#303a7f] text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl shadow-blue-900/10 hover:bg-[#252a5e] disabled:opacity-50 transition-all">Enviar Todos</button>
                        </div>
                    </div>
                    <div className="flex-1 overflow-y-auto custom-scrollbar rounded-[2rem] border-2 border-gray-50 bg-white">
                        <table className="w-full text-left border-collapse">
                            <thead className="sticky top-0 bg-white z-10">
                                <tr className="bg-gray-50/80">
                                    <th className="p-5 text-[10px] font-black text-[#303a7f] uppercase tracking-widest border-b border-gray-100">Empleado</th>
                                    <th className="p-5 text-[10px] font-black text-gray-400 uppercase tracking-widest border-b border-gray-100">Tiendas</th>
                                    <th className="p-5 text-[10px] font-black text-[#6bbdb7] uppercase tracking-widest text-center border-b border-gray-100">Horas</th>
                                    <th className="p-5 text-[10px] font-black text-[#303a7f] uppercase tracking-widest text-right border-b border-gray-100">Monto</th>
                                    <th className="p-5 text-[10px] font-black text-[#303a7f] uppercase tracking-widest text-center border-b border-gray-100">Acciones</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y-2 divide-gray-50">
                                {filteredEmployees.map(emp => {
                                    const totalHrs = (Number(emp.semana1 || 0) + Number(emp.semana2 || 0) + Number(emp.pe || 0));
                                    const email = emp.email_tax;
                                    return (
                                        <tr key={emp.id} className="hover:bg-blue-50/10 transition-colors">
                                            <td className="p-5"><div className="flex flex-col"><span className="text-sm font-black text-[#303a7f] uppercase">{emp.nombre}</span><span className="text-[10px] font-bold text-gray-400">{email || 'SIN CORREO'}</span></div></td>
                                            <td className="p-5"><div className="flex flex-wrap gap-1">{emp.stores.map(s => <span key={s} className="text-[8px] font-black bg-gray-100 text-gray-500 px-2 py-0.5 rounded-md">{s}</span>)}</div></td>
                                            <td className="p-5 text-center text-sm font-black text-[#6bbdb7]">{totalHrs.toFixed(2)}h</td>
                                            <td className="p-5 text-right text-sm font-black text-[#303a7f]">${emp.totalPay.toLocaleString('en-US', { minimumFractionDigits: 2 })}</td>
                                            <td className="p-5">
                                                <div className="flex items-center justify-center gap-2">
                                                    {(paEmailsSent[`${selectedPeriod?.range.replace(/\s+/g, '')}#${emp.id}`] || sentPayStubs[emp.id]) ? <span className="text-[9px] font-black text-teal-600 bg-teal-50 px-3 py-1.5 rounded-full flex items-center gap-2"><Check size={12} /> ENVIADO</span> : (
                                                        <>
                                                            <button onClick={async () => {
                                                                setNotificationModal({ isOpen: true, type: 'loading', message: `Generando PDF...` });
                                                                const pdf = await generatePayStubPDF(emp.id);
                                                                if (pdf) {
                                                                    const blob = await (await fetch(`data:application/pdf;base64,${pdf}`)).blob();
                                                                    setPreviewPdf({ isOpen: true, url: URL.createObjectURL(blob), name: emp.nombre });
                                                                    setNotificationModal({ isOpen: false, type: 'loading', message: '' });
                                                                }
                                                            }} className="p-2 text-[#6bbdb7] hover:bg-[#6bbdb7] hover:text-white rounded-lg transition-all"><Eye size={16} /></button>
                                                            <button onClick={() => handleSendIndividual(emp)} disabled={!email} className="p-2 bg-[#303a7f] text-white hover:bg-[#252a5e] rounded-lg disabled:opacity-30 transition-all"><Send size={16} /></button>
                                                        </>
                                                    )}
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>
                </div>
            </main>
            <div className="absolute left-[-9999px] top-0 pointer-events-none select-none opacity-0">
                {selectedPeriod && biweeklyEmployees.map(emp => (
                    <PayStubPDF
                        key={`stub-tpl-${emp.id}`}
                        employee={{
                            ...emp,
                            codigo: emp.id.split('_')[1],
                            stubId: emp.id,
                            hoursW1: emp.semana1,
                            earningsW1: (parseFloat(emp.semana1) || 0) * emp.rate,
                            hoursW2: emp.semana2,
                            earningsW2: (parseFloat(emp.semana2) || 0) * emp.rate,
                            peEarnings: emp.peEarnings || (emp.totalPay - ((Number(emp.semana1) + Number(emp.semana2)) * emp.rate) - (Number(emp.csgEarnings) || 0) - (Number(emp.adminEarnings) || 0)),
                            csgEarnings: emp.csgEarnings || 0,
                            adminEarnings: emp.adminEarnings || 0
                        }}
                        period={selectedPeriod}
                        store="Global"
                    />
                ))}
            </div>
            {previewPdf.isOpen && (
                <div className="fixed inset-0 z-[600] flex items-center justify-center p-8 backdrop-blur-md bg-white/20">
                    <div className="bg-white w-full max-w-4xl h-[90vh] rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden border">
                        <div className="p-6 border-b flex justify-between items-center">
                            <h4 className="text-sm font-black uppercase text-[#303a7f]">Vista Previa: {previewPdf.name}</h4>
                            <button onClick={() => setPreviewPdf({ ...previewPdf, isOpen: false })} className="p-2 hover:bg-red-50 rounded-xl"><X /></button>
                        </div>
                        <iframe src={`${previewPdf.url}#toolbar=0`} className="flex-1 w-full" />
                    </div>
                </div>
            )}
            <EmailNotificationModal isOpen={notificationModal.isOpen} type={notificationModal.type} message={notificationModal.message} onOk={() => setNotificationModal({ ...notificationModal, isOpen: false })} />
        </div>
    );
};


const BiometricTableIVRModal = ({ isOpen, onClose, onOpenDetails, data, fechaDesde, getFormattedDateForDay, employees = [], payrollStore = '' }) => {
    if (!isOpen) return null;

    const handleDownloadExcel = () => {
        const wb = XLSX.utils.book_new();
        const ws = XLSX.utils.aoa_to_sheet([
            [payrollStore || "Nombre de Tienda"],
            ["Nombre y Apellidos", "Código", "Cargo", "Domingo", "Lunes", "Martes", "Miercoles", "Jueves", "Viernes", "Sabado", "TOTAL"]
        ]);

        const rowsToInsert = data.map(row => {
            const empCode = row.nombre ? row.nombre.toString().trim() : "";
            // Buscar empleado en la base de datos local para obtener nombre y cargo reales si existen
            const localMatch = (employees || []).find(e =>
                e.codigo_empleado && e.codigo_empleado.toString().trim() === empCode &&
                e.tienda === payrollStore
            );

            return [
                localMatch ? localMatch.nombre : `Empleado ${empCode}`,
                empCode,
                localMatch ? localMatch.cargo : "Janitorial",
                row.domingo || "0:00",
                row.lunes || "0:00",
                row.martes || "0:00",
                row.miercoles || "0:00",
                row.jueves || "0:00",
                row.viernes || "0:00",
                row.sabado || "0:00",
                row.total || "0:00"
            ];
        });

        XLSX.utils.sheet_add_aoa(ws, rowsToInsert, { origin: 2 });
        XLSX.utils.book_append_sheet(wb, ws, "Reporte IVR");
        XLSX.writeFile(wb, `Reporte_IVR_${(payrollStore || 'Tienda').replace(/\s+/g, '_')}_${new Date().getTime()}.xlsx`);
    };

    return (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-4 sm:p-6 backdrop-blur-xl bg-[#6bbdb7]/10 animate-in fade-in duration-300">
            <div className="bg-white w-full h-[90vh] rounded-[3rem] shadow-[0_32px_120px_-20px_rgba(107,189,183,0.3)] border-2 border-[#6bbdb7]/20 flex flex-col overflow-hidden animate-in zoom-in-95 slide-in-from-bottom-12 duration-500">
                {/* Header */}
                <div className="p-8 border-b-2 border-gray-50 flex items-center justify-between bg-gradient-to-r from-teal-50/50 to-transparent">
                    <div className="flex items-center gap-5">
                        <div className="p-4 bg-[#6bbdb7] text-white rounded-2xl shadow-lg shadow-teal-900/20">
                            <Clock8 size={24} />
                        </div>
                        <div>
                            <div className="flex items-center gap-3 mb-1">
                                <h3 className="text-2xl font-black text-[#303a7f] tracking-tighter uppercase leading-none">Tabla IVR (Biométrico)</h3>
                                <div className="px-3 py-1 bg-teal-100/50 rounded-full border border-teal-200">
                                    <span className="text-[10px] font-black text-[#6bbdb7] uppercase tracking-widest">{data.length} Empleados</span>
                                </div>
                            </div>
                            <p className="text-[#6bbdb7] font-black uppercase text-[10px] tracking-[0.2em] opacity-80">Resultado de procesamiento inteligente de ponches</p>
                        </div>
                    </div>
                    <div className="flex items-center gap-3">
                        <button
                            onClick={onOpenDetails}
                            className="p-3 bg-red-50 text-red-500 rounded-2xl border-2 border-red-100 shadow-sm flex items-center gap-2 text-[10px] font-black uppercase tracking-widest hover:bg-red-100 transition-all active:scale-95"
                            title="Ver detalles de inconsistencias"
                        >
                            <Info size={16} />
                            Detalles
                        </button>
                        <button
                            onClick={handleDownloadExcel}
                            className="p-3 bg-[#303a7f] text-white rounded-2xl border-2 border-[#303a7f]/10 shadow-lg shadow-blue-900/10 flex items-center gap-2 text-[10px] font-black uppercase tracking-widest hover:bg-[#252a5e] transition-all active:scale-95"
                            title="Descargar reporte en formato Excel"
                        >
                            <Download size={16} />
                            Descargar Reporte
                        </button>
                        <button
                            onClick={onClose}
                            className="flex items-center gap-3 px-6 py-3 bg-white border-2 border-[#6bbdb7]/20 text-[#6bbdb7] rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-teal-50 transition-all active:scale-95 shadow-sm"
                        >
                            <ArrowLeft size={16} />
                            Volver
                        </button>
                    </div>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto p-8">
                    <div className="overflow-x-auto rounded-[2rem] border-[3px] border-gray-100 shadow-sm">
                        <table className="w-full text-left border-collapse">
                            <thead>
                                <tr className="bg-gray-50/50">
                                    <th className="p-5 text-[10px] font-black text-[#303a7f] uppercase tracking-widest border-b-[3px] border-gray-100">ID Empleado / Nombre</th>
                                    {['Dom', 'Lun', 'Mar', 'Mie', 'Jue', 'Vie', 'Sab'].map((day, idx) => (
                                        <th key={day} className="p-5 text-[10px] font-black text-[#6bbdb7] uppercase tracking-widest text-center border-b-[3px] border-l-[3px] border-teal-50">
                                            <div className="flex flex-col items-center">
                                                <span>{day}</span>
                                                <span className="text-[8px] text-[#6bbdb7]/60 font-bold">
                                                    {fechaDesde ? getFormattedDateForDay(fechaDesde, idx) : '--/--'}
                                                </span>
                                            </div>
                                        </th>
                                    ))}
                                    <th className="p-5 text-[10px] font-black text-[#303a7f] uppercase tracking-widest text-right border-b-[3px] border-l-[3px] border-gray-100 min-w-[120px] bg-[#6bbdb7]/5">
                                        Total Biométrico
                                    </th>
                                </tr>
                            </thead>
                            <tbody className="divide-y-[3px] divide-gray-100">
                                {data.map((row, idx) => (
                                    <tr key={idx} className="hover:bg-teal-50/10 transition-colors">
                                        <td className="p-6 border-r-[2px] border-gray-50">
                                            <span className="text-sm font-black text-[#303a7f] uppercase leading-tight">{row.nombre}</span>
                                        </td>
                                        {['domingo', 'lunes', 'martes', 'miercoles', 'jueves', 'viernes', 'sabado'].map(day => {
                                            const value = row[day];
                                            const isZero = !value || value === 0 || value === '0' || value === '0h' || value === '00:00' || value === '0:00';
                                            return (
                                                <td key={day} className="p-6 text-center border-l-[3px] border-gray-100">
                                                    <span className={`text-sm font-black tabular-nums ${!isZero ? 'text-[#6bbdb7]' : 'text-gray-200'}`}>
                                                        {!isZero ? (value.toString().includes('h') ? value : `${value}h`) : '0h'}
                                                    </span>
                                                </td>
                                            );
                                        })}
                                        <td className="p-6 text-right bg-teal-50/30 border-l-[3px] border-gray-100">
                                            <span className="text-base font-black text-[#6bbdb7] tabular-nums">
                                                {row.total.toString().includes('h') ? row.total : `${row.total}h`}
                                            </span>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        </div>
    );
};

const EmployeeVerificationModal = ({ isOpen, onClose, results, onAddAll, stores, employees, massImportMode = false }) => {
    const [localResults, setLocalResults] = useState([]);
    const [searchingIdx, setSearchingIdx] = useState(null);
    const [manualSearchTerm, setManualSearchTerm] = useState('');

    useEffect(() => {
        // Inicializar resoluciones basadas en el tipo
        const initial = (results || []).map(res => {
            const baseObj = {
                ...res,
                resolvedEmployee: res.type === 'verified' || res.type === 'suggested' ? res.employee : null
            };
            return baseObj;
        });
        setLocalResults(initial);
    }, [results]);

    if (!isOpen) return null;

    const formatHistory = (history) => {
        if (!Array.isArray(history) || history.length === 0) return null;
        const uniqueStores = [...new Set(history.map(h => h.tienda))].reverse().slice(0, 3);
        return uniqueStores.join(", ");
    };

    const handleUpdateResolution = (index, employee) => {
        const updated = [...localResults];
        updated[index].resolvedEmployee = employee;
        updated[index].employee = employee; // Asegura que el nombre en la UI cambie
        updated[index].isNew = false;
        // Si era nuevo o ambiguo, lo pasamos a 'suggested' para que muestre la UI de confirmado
        if (updated[index].type === 'new' || updated[index].type === 'ambiguous') {
            updated[index].type = 'suggested';
        }
        setLocalResults(updated);
    };

    const handleExcludeResolution = (index) => {
        const updated = [...localResults];
        updated[index].isExcluded = !updated[index].isExcluded;
        setLocalResults(updated);
    };

    const handleFinalize = () => {
        onAddAll(localResults);
    };

    return (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-0 backdrop-blur-xl bg-[#303a7f]/20 animate-in fade-in duration-300">
            <div className="bg-white w-full max-w-full h-full flex flex-col overflow-hidden animate-in zoom-in-95 slide-in-from-bottom-12 duration-500">
                {/* Header */}
                <div className="p-4 border-b-2 border-gray-50 flex items-center justify-between bg-gradient-to-r from-gray-50/50 to-transparent shrink-0">
                    <div className="flex items-center gap-3">
                        <div className="p-3 bg-[#303a7f] text-white rounded-2xl shadow-lg shadow-blue-900/20">
                            <ShieldCheck size={20} />
                        </div>
                        <div>
                            <h3 className="text-lg font-black text-[#303a7f] tracking-tighter uppercase leading-none mb-0.5">Vincular Personal</h3>
                            <p className="text-[#6bbdb7] text-[8px] font-black uppercase tracking-widest opacity-80 truncate max-w-[200px]">Mapeo Inteligente</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="p-2 btn-close-danger rounded-xl transition-all active:scale-90">
                        <X size={22} />
                    </button>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto p-2 space-y-1.5 bg-[#fcfdfe]">
                    {localResults.length === 0 ? (
                        <div className="h-full flex flex-col items-center justify-center opacity-30 italic">
                            <CheckCircle size={48} className="mb-4 text-green-500" />
                            <p className="text-xs font-black uppercase tracking-[0.3em]">Todo el personal está al día</p>
                        </div>
                    ) : (
                        localResults.map((res, idx) => (
                            <div key={idx} className={`group relative ${res.isExcluded ? 'opacity-50' : ''}`}>
                                <div className={`flex flex-col gap-2 py-2.5 px-3 rounded-xl border-2 transition-all duration-200 hover:shadow-md ${res.isExcluded ? 'bg-gray-100 border-red-200' : res.resolvedEmployee ? 'bg-green-50/20 border-green-100' : 'bg-white border-gray-100'
                                    }`}>
                                    {/* Top: Excel Data */}
                                    <div className="flex items-start justify-between gap-2">
                                        <div className="min-w-0 flex-1">
                                            <div className="flex items-center gap-2 mb-0.5 flex-wrap">
                                                <span className="text-[7px] font-black text-gray-400 uppercase tracking-widest">En Excel</span>
                                                {res.isExcluded && (
                                                    <div className="px-1.5 py-0.5 bg-red-500 text-white rounded text-[7px] font-black uppercase tracking-tight flex items-center gap-1">
                                                        <Trash2 size={8} /> Excluido
                                                    </div>
                                                )}
                                                {!res.isExcluded && res.type === 'ambiguous' && (
                                                    <div className="px-1.5 py-0.5 bg-amber-500 text-white rounded text-[7px] font-black uppercase tracking-tight flex items-center gap-1">
                                                        <AlertTriangle size={8} /> Duplicado
                                                    </div>
                                                )}
                                            </div>
                                            <h4 className="text-[12px] font-black text-gray-700 uppercase leading-tight break-words">{res.excelRow.nombre}</h4>
                                            <p className="text-[9px] font-bold text-gray-400 mt-0.5">ID: {res.excelRow.codigo || '---'} | {res.excelRow.cargo}</p>
                                        </div>
                                        {res.resolvedEmployee ? (
                                            <div className="w-7 h-7 rounded-full bg-green-100 text-green-600 flex items-center justify-center shadow-sm shrink-0" title="Auto-asociado">
                                                <Check size={16} strokeWidth={3} />
                                            </div>
                                        ) : (
                                            <div className="w-7 h-7 rounded-full bg-red-50 text-red-400 flex items-center justify-center shadow-sm shrink-0 opacity-50" title="Sin asociación">
                                                <X size={16} strokeWidth={3} />
                                            </div>
                                        )}
                                    </div>

                                    {/* Middle: Match/Suggested */}
                                    {res.resolvedEmployee ? (
                                        <div className="flex items-center gap-2 text-green-600 animate-in slide-in-from-left-2 transition-all">
                                            <div className="w-6 h-6 rounded-lg bg-green-50 flex items-center justify-center shrink-0">
                                                <UserCheck size={14} />
                                            </div>
                                            <div className="flex flex-col min-w-0">
                                                <h5 className="text-[11px] font-black uppercase leading-tight truncate">{res.resolvedEmployee.nombre}</h5>
                                                <div className="flex items-center gap-2 mt-0.5 flex-wrap">
                                                    <span className="text-[8px] font-black bg-green-100/50 px-1.5 py-0.5 rounded">ID {res.resolvedEmployee.codigo_empleado}</span>
                                                    <span className="text-[8px] font-bold opacity-60 italic truncate max-w-[150px]">
                                                        {res.resolvedEmployee.tienda} {formatHistory(res.resolvedEmployee.locationHistory) ? `(${formatHistory(res.resolvedEmployee.locationHistory)})` : ''}
                                                    </span>
                                                </div>
                                            </div>
                                        </div>
                                    ) : res.type === 'ambiguous' ? (
                                        <div className="flex items-center gap-2 overflow-x-auto pb-1 no-scrollbar flex-nowrap">
                                            <span className="text-[8px] font-black text-amber-600 uppercase shrink-0 mr-1">Elegir:</span>
                                            {res.matches.map((m, midx) => (
                                                <button
                                                    key={midx}
                                                    onClick={() => handleUpdateResolution(idx, m)}
                                                    className="shrink-0 p-2 bg-amber-50 border border-amber-200 rounded-xl hover:border-amber-400 transition-all text-left w-[120px]"
                                                >
                                                    <p className="text-[9px] font-black text-amber-700 leading-tight truncate">{m.nombre}</p>
                                                    <p className="text-[7px] font-bold text-amber-600/60 mt-0.5">ID: {m.codigo_empleado}</p>
                                                </button>
                                            ))}
                                        </div>
                                    ) : (
                                        <div className="flex items-center gap-2 text-gray-300 italic opacity-60">
                                            <div className="w-6 h-6 rounded-lg bg-gray-50 flex items-center justify-center shrink-0">
                                                <UserMinus size={14} />
                                            </div>
                                            <span className="text-[10px] font-black uppercase tracking-widest">Sin coincidencia automática</span>
                                        </div>
                                    )}

                                    {/* Bottom: Options */}
                                    <div className="flex items-center justify-end gap-2 pt-1 border-t border-gray-100">
                                        {res.isExcluded ? (
                                            <button
                                                onClick={() => handleExcludeResolution(idx)}
                                                className="px-3 py-1.5 bg-red-50 text-red-500 rounded-xl text-[9px] font-black uppercase tracking-widest border border-red-100 hover:bg-red-500 hover:text-white transition-all active:scale-95 shadow-sm flex items-center gap-1.5"
                                                title="Restaurar Empleado"
                                            >
                                                <ArrowLeftRight size={12} />
                                                Restaurar
                                            </button>
                                        ) : (
                                            <>
                                                <button
                                                    onClick={() => { setSearchingIdx(idx); setManualSearchTerm(res.excelRow.nombre || ''); }}
                                                    className="px-3 py-1.5 bg-gray-50 text-[#303a7f] rounded-xl text-[9px] font-black uppercase tracking-widest border border-gray-100 hover:bg-[#303a7f] hover:text-white hover:border-[#303a7f] transition-all active:scale-95 shadow-sm flex items-center gap-1.5"
                                                >
                                                    <Search size={12} />
                                                    Buscar
                                                </button>
                                                <button
                                                    onClick={() => handleExcludeResolution(idx)}
                                                    className="p-1.5 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all border border-transparent hover:border-red-100"
                                                    title="Excluir/Ignorar Empleado"
                                                >
                                                    <Trash2 size={16} />
                                                </button>
                                            </>
                                        )}
                                    </div>
                                </div>
                            </div>
                        ))
                    )}
                </div>

                {/* Buscador de Empleados Manual */}
                {searchingIdx !== null && (
                    <div className="absolute inset-0 z-[100] flex items-center justify-center p-0 backdrop-blur-md bg-[#303a7f]/40 animate-in fade-in duration-300">
                        <div className="bg-white w-full h-full flex flex-col overflow-hidden">
                            <div className="p-4 border-b-2 border-gray-50 flex items-center justify-between shrink-0">
                                <div className="flex items-center gap-3">
                                    <div className="p-2.5 bg-blue-50 text-blue-600 rounded-xl">
                                        <Search size={18} />
                                    </div>
                                    <h4 className="text-base font-black text-[#303a7f] tracking-tighter uppercase">Vincular Registro</h4>
                                </div>
                                <button onClick={() => setSearchingIdx(null)} className="p-2 btn-close-danger rounded-xl">
                                    <X size={20} />
                                </button>
                            </div>

                            <div className="p-4 bg-gray-50/50 shrink-0">
                                <div className="relative group">
                                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300 group-focus-within:text-[#303a7f] transition-colors" size={16} />
                                    <input
                                        autoFocus
                                        type="text"
                                        placeholder="Buscar por Nombre o ID..."
                                        value={manualSearchTerm}
                                        onChange={(e) => setManualSearchTerm(e.target.value)}
                                        className="w-full bg-white border-2 border-gray-100 rounded-xl pl-11 pr-4 py-3 text-sm font-bold text-[#303a7f] outline-none focus:border-[#303a7f]/30 transition-all shadow-sm"
                                    />
                                </div>
                            </div>

                            <div className="flex-1 overflow-y-auto p-4 space-y-2">
                                {employees
                                    .filter(emp => {
                                        const query = manualSearchTerm.toLowerCase();
                                        return emp.nombre?.toLowerCase().includes(query) ||
                                            emp.codigo_empleado?.toLowerCase().includes(query);
                                    })
                                    .slice(0, 50)
                                    .map((emp, eidx) => (
                                        <button
                                            key={eidx}
                                            onClick={() => {
                                                handleUpdateResolution(searchingIdx, emp);
                                                setSearchingIdx(null);
                                            }}
                                            className="w-full p-3 bg-white border-2 border-gray-100 rounded-xl hover:border-[#6bbdb7] hover:bg-teal-50/30 transition-all flex items-center justify-between group"
                                        >
                                            <div className="text-left min-w-0 flex-1 mr-2">
                                                <p className="text-[13px] font-black text-[#303a7f] uppercase leading-tight truncate">{emp.nombre}</p>
                                                <div className="flex items-center gap-2 mt-0.5 flex-wrap">
                                                    <span className="text-[9px] font-black text-[#6bbdb7] uppercase tracking-widest">ID: {emp.codigo_empleado}</span>
                                                    <span className="text-[9px] text-gray-400 font-bold uppercase">• {emp.cargo}</span>
                                                </div>
                                            </div>
                                            <div className="flex items-center gap-2 shrink-0">
                                                <span className="text-[8px] bg-blue-50 text-blue-600 px-2 py-0.5 rounded font-black uppercase max-w-[100px] truncate">{emp.tienda || 'Sin Asignar'}</span>
                                                <ChevronRight size={16} className="text-gray-300 group-hover:translate-x-1 group-hover:text-[#6bbdb7] transition-all" />
                                            </div>
                                        </button>
                                    ))
                                }
                                {manualSearchTerm && employees.filter(emp => {
                                    const query = manualSearchTerm.toLowerCase();
                                    return emp.nombre?.toLowerCase().includes(query) ||
                                        emp.codigo_empleado?.toLowerCase().includes(query);
                                }).length === 0 && (
                                        <div className="py-12 text-center text-gray-300 italic uppercase text-[10px] font-black tracking-widest">
                                            No se encontraron coincidencias en la base de datos
                                        </div>
            )}
                            </div>
                        </div>
                    </div>
                )}

                {/* Footer */}
                <div className="p-8 border-t-2 border-gray-50 bg-gray-50/30 flex flex-col items-center gap-6">
                    <div className="flex items-center gap-6">
                        <div className="flex flex-col">
                            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Empleados</p>
                            <p className="text-xl font-black text-[#303a7f] leading-none">{localResults.filter(r => !r.isExcluded).length}</p>
                        </div>
                        <div className="h-8 w-px bg-gray-200" />
                        <div className="flex gap-4">
                            <div className="flex flex-col">
                                <span className="text-[8px] font-black text-green-500 uppercase tracking-wider">Listos</span>
                                <span className="text-xs font-black text-gray-600">{localResults.filter(r => r.resolvedEmployee && !r.isExcluded).length}</span>
                            </div>
                            <div className="flex flex-col">
                                <span className="text-[8px] font-black text-amber-500 uppercase tracking-wider">Pendientes</span>
                                <span className="text-xs font-black text-gray-600">{localResults.filter(r => !r.resolvedEmployee && !r.isExcluded).length}</span>
                            </div>
                            <div className="flex flex-col">
                                <span className="text-[8px] font-black text-red-500 uppercase tracking-wider">Excluidos</span>
                                <span className="text-xs font-black text-gray-600">{localResults.filter(r => r.isExcluded).length}</span>
                            </div>
                        </div>
                    </div>

                    <button
                        disabled={localResults.filter(r => {
                            if (massImportMode && r.type === 'new') return false;
                            return !r.resolvedEmployee && !r.isExcluded;
                        }).length > 0}
                        onClick={handleFinalize}
                        className={`px-12 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl transition-all active:scale-95 flex items-center gap-3 whitespace-nowrap ${localResults.filter(r => {
                            if (massImportMode && r.type === 'new') return false;
                            return !r.resolvedEmployee && !r.isExcluded;
                        }).length > 0
                            ? 'bg-gray-200 text-gray-400 cursor-not-allowed'
                            : 'bg-[#303a7f] text-white shadow-blue-900/20 hover:bg-[#252a5e]'
                            }`}
                    >
                        <Save size={14} />
                        {massImportMode ? 'Sincronizar Personal' : 'Sincronizar Personal'}
                    </button>
                </div>
            </div>
        </div>
    );
};

const PayrollProgressModal = ({ isOpen, step, current, total }) => {
    useEffect(() => {
        if (isOpen) {
            document.body.style.overflow = 'hidden';
        } else {
            document.body.style.overflow = 'unset';
        }
        return () => { document.body.style.overflow = 'unset'; };
    }, [isOpen]);

    if (!isOpen) return null;
    const percentage = total > 0 ? Math.round((current / total) * 100) : 0;

    const steps = {
        'supervisor': { title: 'Procesando Data', icon: FileText, color: '#303a7f' },
        'ia': { title: 'Motor de Inteligencia Artificial', icon: Cpu, color: '#6bbdb7' },
        'crossover': { title: 'Cruzando Datos de Nómina', icon: Settings, color: '#303a7f' }
    };

    const currentStep = steps[step] || steps['supervisor'];

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 backdrop-blur-2xl bg-[#303a7f]/40 animate-in fade-in duration-500">
            <div className="bg-white w-full max-w-md rounded-[3rem] p-10 shadow-[0_32px_120px_-20px_rgba(48,58,127,0.4)] border-2 border-white/50 text-center animate-in zoom-in-95 duration-500">
                <div className="mb-8 relative inline-block">
                    <div className="w-24 h-24 rounded-full border-4 border-gray-100 border-t-[#6bbdb7] animate-spin"></div>
                    <div className="absolute inset-0 flex items-center justify-center">
                        {currentStep.icon && <currentStep.icon size={32} style={{ color: currentStep.color }} className="animate-pulse" />}
                    </div>
                </div>

                <h3 className="text-2xl font-black text-[#303a7f] tracking-tighter uppercase mb-2">{currentStep.title}</h3>
                <p className="text-gray-400 text-[10px] font-black uppercase tracking-widest mb-8">
                    {step === 'ia' ? 'Analizando registros biométricos...' : `Procesando registro ${current} de ${total}`}
                </p>

                {/* Progress Bar Container */}
                <div className="w-full h-4 bg-gray-100 rounded-full overflow-hidden mb-4 border-2 border-gray-50 shadow-inner">
                    <div
                        className="h-full bg-gradient-to-r from-[#303a7f] to-[#6bbdb7] transition-all duration-500 ease-out"
                        style={{ width: `${step === 'ia' && current === 0 ? '50%' : `${percentage}%`}` }}
                    />
                </div>

                <p className="text-[8px] text-gray-300 font-black uppercase tracking-[0.3em] animate-pulse">
                    No cierre la ventana ni refresque la página
                </p>
            </div>
        </div>
    );
};

