// Utilidades de Fecha y Formato para Facturación
const toISODate = (dateStr) => {
    if (!dateStr) return '';

    // Si ya viene en ISO
    if (dateStr.includes('-') && !dateStr.includes('/')) return dateStr;

    const parts = dateStr.split('/').map(p => p.trim());
    if (parts.length < 3) return '';

    // Detección inteligente: si el primer segmento es > 12, es DD/MM/YYYY
    let m = parts[0], d = parts[1], y = parts[2];
    if (parseInt(m) > 12) { [m, d] = [d, m]; }

    return `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
};

const fromISODate = (yyyymmdd) => {
    if (!yyyymmdd || !yyyymmdd.includes('-')) return '';
    const [y, m, d] = yyyymmdd.split('-');
    return `${String(m).padStart(2, '0')}/${String(d).padStart(2, '0')}/${y}`;
};

const formatDate = (dateStr) => {
    if (!dateStr || dateStr === '--/--/--') return '';

    // Si viene en ISO (ej: del picker)
    if (dateStr.includes('-') && !dateStr.includes('/')) {
        return fromISODate(dateStr);
    }

    // Si viene en formato con barras, aseguramos mm/dd/yyyy
    const parts = dateStr.split('/').map(p => p.trim());
    if (parts.length === 3) {
        let m = parts[0], d = parts[1], y = parts[2];
        if (parseInt(m) > 12) { [m, d] = [d, m]; }
        return `${String(m).padStart(2, '0')}/${String(d).padStart(2, '0')}/${y}`;
    }

    return dateStr;
};


const formatCurrencyInput = (value) => {
    if (value === null || value === undefined) return '';
    // Solo permitimos números y punto
    let clean = String(value).replace(/[^0-9.]/g, '');
    let parts = clean.split('.');

    // Formatear parte entera con comas
    parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');

    // Reubicar el punto si existe
    return parts.length > 1 ? parts[0] + '.' + parts[1].slice(0, 2) : parts[0];
};

const BillingView = ({
    storeName,
    historyData = [],
    specialHistoryData = [],
    isSyncing = false,
    onOpenVWH = () => { },
    onOpenQuincenaVWH = () => { },
    onOpenPE = () => { },
    onUpdateManual = () => { },
    onUpdateManualPE = () => { },
    vwhEmailsSent = {},
    peEmailsSent = {},
    filterYear = new Date().getFullYear()
}) => {
    const normalizeKey = (k) => String(k || '').toLowerCase().trim();
    const isAZPEN = String(storeName).trim().toUpperCase() === 'UNITED PARCEL SERVICE AZPEN';

    // --- LÓGICA TABLA VWH (Nómina Regular) ---
    // Filtrado y ordenado seguro (Safe-Sort) - incluye filtro por año seleccionado
    const activeRecords = (historyData || [])
        .filter(h => {
            if (!h || !h.nombre || String(h.nombre).trim() !== String(storeName).trim()) return false;
            // Filtrar por año: extraer el año de fecha_inicio (formato MM/DD/YYYY)
            if (h.fecha_inicio) {
                const parts = String(h.fecha_inicio).split('/');
                if (parts.length === 3 && Number(parts[2]) !== filterYear) return false;
            }
            return true;
        })
        .sort((a, b) => {
            try {
                if (!a.fecha_inicio || !b.fecha_inicio) return 0;
                const partsA = a.fecha_inicio.split('/');
                const partsB = b.fecha_inicio.split('/');
                if (partsA.length < 3 || partsB.length < 3) return 0;
                const [mA, dA, yA] = partsA;
                const [mB, dB, yB] = partsB;
                return new Date(yA, mA - 1, dA) - new Date(yB, mB - 1, dB);
            } catch (e) { return 0; }
        });

    let tableData = [];

    if (isAZPEN) {
        const quincenasMap = {};

        activeRecords.forEach(h => {
            if (!h.fecha_inicio) return;
            const partsStart = h.fecha_inicio.split('/');
            if (partsStart.length !== 3) return;
            const [mS, dS, yS] = partsStart.map(Number);
            const baseStartDate = new Date(yS, mS - 1, dS);

            const getOrInitQuincena = (dateObj) => {
                const y = dateObj.getFullYear();
                const m = dateObj.getMonth() + 1;
                const d = dateObj.getDate();
                const qNumber = d <= 15 ? 1 : 2;
                const qKey = `${y}-${String(m).padStart(2, '0')}-Q${qNumber}`;

                if (!quincenasMap[qKey]) {
                    const mStr = String(m).padStart(2, '0');
                    const lastDay = new Date(y, m, 0).getDate();
                    const qStart = qNumber === 1 ? `${mStr}/01/${y}` : `${mStr}/16/${y}`;
                    const qEnd = qNumber === 1 ? `${mStr}/15/${y}` : `${mStr}/${lastDay}/${y}`;

                    quincenasMap[qKey] = {
                        _ids: new Set(),
                        id: `Q-${qStart.replace(/\//g, '')}-${qEnd.replace(/\//g, '')}`,
                        radicacion: '',
                        semana: `${qStart} - ${qEnd}`,
                        fecha_inicio: qStart,
                        fecha_fin: qEnd,
                        nombre_store: h.nombre || '',
                        horas: 0,
                        facturacion: 484.33,
                        costos: 0,
                        utilidad: 0,
                        pago: '',
                        fecha_pago: '',
                        wos: '',
                        pagada: false,
                        _qKey: qKey
                    };
                }

                const q = quincenasMap[qKey];
                q._ids.add(h.codigo);

                // Evitar contaminación cruzada: solo asociar ID y metadatos si la semana coincide con la quincena correspondiente
                const hQNumber = dS <= 15 ? 1 : 2;
                const hQKey = `${yS}-${String(mS).padStart(2, '0')}-Q${hQNumber}`;

                if (qKey === hQKey) {
                    if (String(h.codigo).startsWith('Q-')) {
                        q.id = h.codigo;
                        // Para AZPEN, solo populamos metadatos financieros y radicación desde la fila quincenal unificada (Q-)
                        // para mantener aisladas y vírgenes las semanas individuales.
                        if (h['Fecha Rad.'] || h['fecha rad.']) q.radicacion = h['Fecha Rad.'] || h['fecha rad.'];
                        if (h['pago'] || h['Pago']) q.pago = h['pago'] || h['Pago'];
                        if (h['fecha de pago'] || h['Fecha de Pago']) q.fecha_pago = h['fecha de pago'] || h['Fecha de Pago'];
                        if (h['wos'] || h['WOS']) q.wos = h['wos'] || h['WOS'];
                        const statusVal = h['Status'] || h['status'] || '';
                        q.pagada = (statusVal === 'Paid');
                    }
                }

                return q;
            };

            try {
                if (h && h.data_json) {
                    const data = JSON.parse(h.data_json);

                    const helperHhmmToDecimal = (v) => {
                        if (!v || v === 'X' || v === '0:00') return 0;
                        const s = String(v);
                        if (s.includes(':')) {
                            const [hrs, min] = s.split(':').map(Number);
                            return hrs + (min || 0) / 60;
                        }
                        return parseFloat(s) || 0;
                    };

                    let addedHours = false;

                    if (data.semanaTableData) {
                        const daysMapping = ['domingo', 'lunes', 'martes', 'miercoles', 'jueves', 'viernes', 'sabado'];
                        let sIdx = 0; let eIdx = 6;
                        if (data.isSplitFragment && data.fragmentRange) {
                            try {
                                const [fmS, fdS, fyS] = data.fragmentRange.start.split('/');
                                const [fmE, fdE, fyE] = data.fragmentRange.end.split('/');
                                sIdx = new Date(fyS, fmS - 1, fdS).getDay();
                                eIdx = new Date(fyE, fmE - 1, fdE).getDay();
                            } catch (e) { sIdx = 0; eIdx = 6; }
                        }

                        data.semanaTableData.forEach(emp => {
                            const empId = `${String(emp.nombre).trim().toLowerCase()}_${String(emp.codigo).trim()}`;
                            const earningRow = (data.earningsTableData || []).find(e => `${String(e.nombre).trim().toLowerCase()}_${String(e.codigo).trim()}` === empId);
                            const rate = earningRow ? (parseFloat(earningRow.rate) || 0) : 0;

                            for (let i = sIdx; i <= eIdx; i++) {
                                const hrs = helperHhmmToDecimal(emp[daysMapping[i]]?.final || 0);
                                if (hrs > 0) {
                                    const currentDate = new Date(baseStartDate.getFullYear(), baseStartDate.getMonth(), baseStartDate.getDate() + (i - sIdx));
                                    const q = getOrInitQuincena(currentDate);
                                    q.horas += hrs;
                                    q.costos += hrs * rate;
                                    addedHours = true;
                                }
                            }
                        });
                    }

                    if (!addedHours && h.fecha_fin) {
                        const [mF, dF, yF] = h.fecha_fin.split('/').map(Number);
                        const q = getOrInitQuincena(new Date(yF, mF - 1, dF));

                        let totalH = 0;
                        let totalC = 0;
                        if (data.kbsBillingTableData) {
                            data.kbsBillingTableData.forEach(r => {
                                const totalVal = parseFloat(rowTotalToNumber(r.total)) || 0;
                                const rateVal = parseFloat(r.rate) || 1;
                                totalH += totalVal / rateVal;
                            });
                        }
                        if (data.earningsTableData) {
                            totalC = data.earningsTableData.reduce((acc, r) => acc + (parseFloat(rowTotalToNumber(r.total)) || 0), 0);
                        }
                        q.horas += totalH;
                        q.costos += totalC;
                    }
                }
            } catch (e) { console.error("[LogicPay] Error parsing history json for AZPEN", e); }
        });

        tableData = Object.values(quincenasMap).map(q => {
            q._ids = Array.from(q._ids);
            q.utilidad = q.facturacion - q.costos;
            return q;
        }).sort((a, b) => a._qKey.localeCompare(b._qKey));

    } else {
        tableData = activeRecords.map(h => {
            let stats = { horas: 0, facturacion: 0, costos: 0 };
            try {
                if (h && h.data_json) {
                    const data = JSON.parse(h.data_json);
                    // --- CÁLCULO DE FACTURACIÓN (KBS) ---
                    if (data.kbsBillingTableData) {
                        data.kbsBillingTableData.forEach(r => {
                            const totalVal = parseFloat(rowTotalToNumber(r.total)) || 0;
                            stats.facturacion += totalVal;
                        });
                    }

                    // --- CÁLCULO DE HORAS (Consistencia con Reporte VWH) ---
                    const helperHhmmToDecimal = (v) => {
                        if (!v || v === 'X' || v === '0:00') return 0;
                        const s = String(v);
                        if (s.includes(':')) {
                            const [h, m] = s.split(':').map(Number);
                            return h + (m || 0) / 60;
                        }
                        return parseFloat(s) || 0;
                    };

                    if (data.semanaTableData) {
                        const daysMapping = ['domingo', 'lunes', 'martes', 'miercoles', 'jueves', 'viernes', 'sabado'];
                        let sIdx = 0;
                        let eIdx = 6;

                        if (data.isSplitFragment && data.fragmentRange) {
                            try {
                                const [mS, dS, yS] = data.fragmentRange.start.split('/');
                                const [mE, dE, yE] = data.fragmentRange.end.split('/');
                                sIdx = new Date(yS, mS - 1, dS).getDay();
                                eIdx = new Date(yE, mE - 1, dE).getDay();
                            } catch (e) {
                                sIdx = 0; eIdx = 6;
                            }
                        }

                        data.semanaTableData.forEach(emp => {
                            for (let i = sIdx; i <= eIdx; i++) {
                                stats.horas += helperHhmmToDecimal(emp[daysMapping[i]]?.final || 0);
                            }
                        });
                    } else if (data.kbsBillingTableData) {
                        // Fallback para registros antiguos
                        data.kbsBillingTableData.forEach(r => {
                            const totalVal = parseFloat(rowTotalToNumber(r.total)) || 0;
                            const rateVal = parseFloat(r.rate) || 1;
                            stats.horas += totalVal / rateVal;
                        });
                    }
                    if (data.earningsTableData) {
                        stats.costos = data.earningsTableData.reduce((acc, r) => acc + (parseFloat(rowTotalToNumber(r.total)) || 0), 0);
                    }
                }
            } catch (e) { console.error("[LogicPay] Error parsing history json", e); }

            const statusVal = h['Status'] || h['status'] || '';
            const isPaid = statusVal === 'Paid';

            return {
                id: h.codigo,
                radicacion: h['Fecha Rad.'] || h['fecha rad.'] || '',
                semana: h.fecha_inicio && h.fecha_fin ? `${h.fecha_inicio} - ${h.fecha_fin}` : 'Período Desconocido',
                fecha_inicio: h.fecha_inicio || '',
                fecha_fin: h.fecha_fin || '',
                nombre_store: h.nombre || '',
                horas: stats.horas || 0,
                facturacion: stats.facturacion || 0,
                costos: stats.costos || 0,
                utilidad: (stats.facturacion || 0) - (stats.costos || 0),
                pago: h['pago'] || h['Pago'] || '',
                fecha_pago: h['fecha de pago'] || h['Fecha de Pago'] || '',
                wos: h['wos'] || h['WOS'] || '',
                pagada: isPaid
            };
        });
    }

    // Filtrar semanas con cero actividad (0 horas), ya que no generan facturación a KBS
    tableData = tableData.filter(item => item.horas > 0);

    // --- LÓGICA TABLA PROYECTOS ESPECIALES (P.E) ---
    // currentYear usa el año seleccionado desde el Motor de Nómina (filterYear)
    const currentYear = filterYear;
    const parseProjectDate = (value) => {
        if (!value) return null;
        const raw = String(value).trim();
        if (/^\d{4}-\d{2}-\d{2}/.test(raw)) {
            const d = new Date(raw);
            return isNaN(d.getTime()) ? null : d;
        }
        if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(raw)) {
            const [m, d, y] = raw.split('/').map(Number);
            const date = new Date(y, m - 1, d);
            return isNaN(date.getTime()) ? null : date;
        }
        const date = new Date(raw);
        return isNaN(date.getTime()) ? null : date;
    };

    const activePERecords = (specialHistoryData || []).filter(h =>
        h && String(h.tienda || '').trim().toLowerCase() === String(storeName || '').trim().toLowerCase() &&
        String(h.visible || h.Visible || '').trim().toLowerCase() !== 'anulado'
    );

    const peTableDataMap = {};
    activePERecords.forEach(h => {
        try {
            if (!h || !h.data_json) return;
            const projectsRaw = JSON.parse(h.data_json);
            const projects = Array.isArray(projectsRaw) ? projectsRaw : [projectsRaw];

            const normalizeFecha = (val) => {
                if (!val) return '--/--/--';
                const s = String(val).trim();
                if (/^\d{4}-\d{2}-\d{2}/.test(s)) {
                    const [y, m, d] = s.split('-');
                    return `${m}/${d.substring(0, 2)}/${y}`;
                }
                if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(s)) return s;
                return s;
            };

            projects.forEach(p => {
                if (!p) return;
                const projectDate = parseProjectDate(p.fecha);
                if (projectDate && projectDate.getFullYear() !== currentYear) return;

                const correlativoKey = String(h.correlativo || h.Correlativo || '').trim();
                const key = p.invoice || `${p.proyecto || 'S-P'}-${p.fecha || '00'}`;
                if (!peTableDataMap[key]) {
                    peTableDataMap[key] = {
                        id: key,
                        correlativo: correlativoKey,
                        invoice: p.invoice || 'N/A',
                        nombre: p.proyecto || p.nombre || 'Proyecto Especial',
                        fecha: normalizeFecha(p.fecha),
                        horas: 0,
                        facturacion: 0,
                        costos: 0,
                        radicacion: h['Fecha Rad.'] || h['fecha rad.'] || '',
                        pago: h['Pago'] || h['pago'] || '',
                        fecha_pago: h['Fecha de Pago'] || h['fecha de pago'] || '',
                        wos: h['WOS'] || h['wos'] || '',
                        pagada: h['pagada'] === true || h['pagada'] === 'true' || (h['Status'] || h['status']) === 'Paid'
                    };
                }

                const employees = Array.isArray(p.employees) ? p.employees : [];
                const hoursFromEmployees = employees.reduce((acc, emp) => acc + (parseFloat(emp.hours) || 0), 0);
                const facturacionFromEmployees = employees.reduce((acc, emp) => acc + ((parseFloat(emp.hours) || 0) * (parseFloat(emp.rateKBS) || 0)), 0);
                const costosFromEmployees = employees.reduce((acc, emp) => acc + ((parseFloat(emp.hours) || 0) * (parseFloat(emp.rateLogic) || 0)), 0);

                peTableDataMap[key].horas += parseFloat(p.horas) || hoursFromEmployees || 0;
                peTableDataMap[key].facturacion += parseFloat(p.total_kbs) || facturacionFromEmployees || 0;
                peTableDataMap[key].costos += parseFloat(p.total_logic) || costosFromEmployees || 0;
            });
        } catch (e) {
            console.error("[LogicPay] Error parsing PE history json", e);
        }
    });

    const peTableData = Object.values(peTableDataMap).map(row => {
        return {
            ...row,
            utilidad: (row.facturacion || 0) - (row.costos || 0)
        };
    }).sort((a, b) => {
        const parseDate = (str) => {
            if (!str || str === '--/--/--') return 0;
            const parts = str.split('/');
            if (parts.length !== 3) return 0;
            return parseInt(parts[2]) * 10000 + parseInt(parts[0]) * 100 + parseInt(parts[1]);
        };
        return parseDate(a.fecha) - parseDate(b.fecha);
    });

    const formatCurrency = (val) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(val);
    function rowTotalToNumber(val) {
        if (!val) return 0;
        return String(val).replace(/[^0-9.-]+/g, "");
    }

    if (!storeName) {
        return (
            <div className="flex flex-col items-center justify-center py-40 opacity-30 text-[#303a7f]">
                <Receipt size={64} className="mb-6 animate-pulse" />
                <p className="text-xl font-black uppercase tracking-[0.4em]">Selecciona una Tienda para Auditar</p>
            </div>
        );
    }

    return (
        <div className="w-full h-full flex flex-col animate-in fade-in duration-700">
            <div className="flex-1 overflow-y-auto custom-scrollbar pb-20">

                {/* SECCIÓN VWH */}
                <div className="mt-6 mb-4 px-6">
                    <div className="flex items-center gap-3">
                        <div className="bg-[#6bbdb7] p-2 rounded-xl shadow-lg shadow-teal-900/10">
                            <FileText className="text-white" size={16} />
                        </div>
                        <div>
                            <h3 className="text-lg font-black text-[#303a7f] tracking-tighter uppercase leading-none">Facturación VWH</h3>
                            <p className="text-gray-400 text-[8px] font-black tracking-[0.4em] uppercase opacity-70 mt-1">Nómina Regular</p>
                        </div>
                        {isSyncing && (
                            <div className="ml-auto flex items-center gap-2 px-3 py-1 bg-[#303a7f]/5 rounded-lg animate-pulse border border-[#303a7f]/10">
                                <div className="w-1.5 h-1.5 bg-[#6bbdb7] rounded-full shadow-[0_0_8px_#6bbdb7]"></div>
                                <span className="text-[9px] font-black text-[#303a7f] uppercase tracking-widest">Sincronizando...</span>
                            </div>
                        )}
                    </div>
                </div>

                <div className="px-3 space-y-2 max-w-full">
                    {tableData.length === 0 ? (
                        <div className="py-16 text-center text-gray-300 font-bold uppercase tracking-widest text-[10px]">No hay registros VWH.</div>
                    ) : tableData.map((row) => {
                        const fi = row.fecha_inicio || '';
                        const ff = row.fecha_fin || '';
                        const sn = row.nombre_store || storeName || '';
                        const rowId = String(row.id || '');
                        const candidateKeys = [
                            rowId,
                            normalizeKey(rowId),
                            `${sn}_${fi}_${ff}`,
                            `${sn.toLowerCase()}_${fi}_${ff}`,
                            `${storeName}_${fi}_${ff}`,
                            `${storeName.toLowerCase()}_${fi}_${ff}`,
                        ];
                        const isSent = (row.radicacion && row.radicacion !== '--/--/--') || candidateKeys.some(k => vwhEmailsSent[k]);
                        return (
                            <div key={row.id} className="bg-gray-50/50 rounded-2xl p-3 border border-gray-100 space-y-2 max-w-full">
                                <div className="flex items-center justify-between gap-2">
                                    <span className={`text-[10px] font-bold uppercase ${row.radicacion ? 'text-[#303a7f]' : 'text-gray-300'}`}>
                                        Rad: {row.radicacion || '--/--/--'}
                                    </span>
                                    <div className="flex items-center gap-1.5">
                                        {isAZPEN ? (
                                            <button onClick={() => onOpenQuincenaVWH(row)} title="Ver Detalle de Nómina Quincenal VWH" className="text-[#303a7f] hover:text-[#6bbdb7] text-[10px] font-bold border-b border-dashed border-[#303a7f]/30 pb-0.5">
                                                {row.semana}
                                            </button>
                                        ) : (
                                            <button onClick={() => onOpenVWH(row.id)} title="Ver Detalle de Nómina VWH" className="text-[#303a7f] hover:text-[#6bbdb7] text-[10px] font-bold border-b border-dashed border-[#303a7f]/30 pb-0.5">
                                                {row.semana}
                                            </button>
                                        )}
                                        {isSent && <Send size={14} className="text-[#6bbdb7] shrink-0" />}
                                    </div>
                                </div>
                                <div className="flex items-center gap-2 flex-wrap">
                                    <span className="text-[10px] font-black text-[#303a7f]">{row.horas.toFixed(1)}H</span>
                                    <span className="text-[10px] text-gray-300">|</span>
                                    <span className="text-[10px] font-black text-[#303a7f]">KBS: {formatCurrency(row.facturacion)}</span>
                                    <span className="text-[10px] font-bold text-red-400">LGM: {formatCurrency(row.costos)}</span>
                                    <span className="text-[10px] text-gray-300">|</span>
                                    <span className={`text-[10px] font-black ${row.utilidad >= 0 ? 'text-teal-600' : 'text-red-500'}`}>
                                        Util: {formatCurrency(row.utilidad)}
                                    </span>
                                </div>
                                <div className="flex items-center gap-1.5 flex-wrap text-[10px]">
                                    <span className="font-black text-[#303a7f]">Pago: {formatCurrencyInput(row.pago) || '$0.00'}</span>
                                    <span className="text-gray-300">|</span>
                                    <span className="font-bold text-gray-400 uppercase">FP: {row.fecha_pago || '--/--/--'}</span>
                                    <span className="text-gray-300">|</span>
                                    <span className={`font-black ${row.wos ? 'text-orange-500' : 'text-gray-300'}`}>WOS: {row.wos || '---'}</span>
                                </div>
                                <label className="flex items-center gap-1.5 cursor-pointer">
                                    <span className="text-[9px] font-black text-gray-400 uppercase">Pagado</span>
                                    <input
                                        type="checkbox"
                                        checked={row.pagada}
                                        onChange={(e) => {
                                            const val = e.target.checked;
                                            if (isAZPEN) {
                                                onUpdateManual(row.id, 'pagada', val);
                                            } else if (row._ids) {
                                                row._ids.forEach(id => onUpdateManual(id, 'pagada', val));
                                            } else {
                                                onUpdateManual(row.id, 'pagada', val);
                                            }
                                        }}
                                        className="w-4 h-4 rounded border-gray-300 text-[#6bbdb7] focus:ring-[#59aba5] cursor-pointer accent-[#6bbdb7] transition-all"
                                    />
                                </label>
                            </div>
                        );
                    })}
                </div>

                {/* Resumen VWH */}
                <div className="px-6 py-10 border-y border-gray-50 flex items-center justify-between bg-[#fcfdfe]/50">
                    <div className="flex gap-12">
                        <div className="flex flex-col"><span className="text-[10px] font-black text-gray-400 uppercase mb-1">Total KBS Facturado</span><span className="text-xl font-black text-[#303a7f]">{formatCurrency(tableData.reduce((acc, r) => acc + r.facturacion, 0))}</span></div>
                        <div className="flex flex-col"><span className="text-[10px] font-black text-gray-400 uppercase mb-1">Costo Operativo</span><span className="text-xl font-black text-red-400">{formatCurrency(tableData.reduce((acc, r) => acc + r.costos, 0))}</span></div>
                        <div className="flex flex-col border-l-2 border-gray-200 pl-12"><span className="text-[10px] font-black text-gray-400 uppercase mb-1">Utilidad Neta LGM</span><span className="text-xl font-black text-[#6bbdb7]">{formatCurrency(tableData.reduce((acc, r) => acc + r.utilidad, 0))}</span></div>
                    </div>
                </div>

                {/* SECCIÓN PROYECTOS ESPECIALES */}
                <div className="mt-12 mb-6 px-6">
                    <div className="flex items-center gap-3">
                        <div className="bg-[#303a7f] p-2 rounded-xl shadow-lg shadow-blue-900/10">
                            <ClipboardCheck className="text-white" size={16} />
                        </div>
                        <div>
                            <h3 className="text-lg font-black text-[#303a7f] tracking-tighter uppercase leading-none">Facturación de Proyectos Especiales</h3>
                            <p className="text-[#6bbdb7] text-[8px] font-black tracking-[0.4em] uppercase opacity-70 mt-1">Auditoría Especial</p>
                        </div>
                    </div>
                </div>

                <div className="px-3 space-y-2 max-w-full">
                    {peTableData.length === 0 ? (
                        <div className="py-16 text-center text-gray-300 font-bold uppercase tracking-widest text-[10px]">No hay registros de Proyectos Especiales.</div>
                    ) : peTableData.map((row) => {
                        const invRaw = String(row.invoice || '');
                        const invNorm = normalizeKey(invRaw);
                        const isSent = (row.radicacion && row.radicacion !== '--/--/--') || peEmailsSent[invNorm];
                        return (
                            <div key={row.id} className="bg-gray-50/50 rounded-2xl p-3 border border-gray-100 space-y-2 max-w-full">
                                <div className="flex items-center justify-between gap-2">
                                    <span className={`text-[10px] font-bold uppercase ${row.radicacion ? 'text-[#303a7f]' : 'text-gray-300'}`}>
                                        Rad: {row.radicacion || '--/--/--'}
                                    </span>
                                    <span className="text-[10px] font-bold text-[#333333]">{row.fecha || '--/--/--'}</span>
                                </div>
                                <div className="flex items-center justify-between gap-2">
                                    <button onClick={() => onOpenPE(row.id)} title="Ver Detalle de Proyecto Especial" className="text-left">
                                        <span className="text-[10px] font-black text-[#303a7f] hover:text-[#6bbdb7] border-b border-dashed border-[#303a7f]/30 pb-0.5">{row.nombre}</span>
                                        <span className="text-[8px] font-bold text-gray-400 ml-1.5">Inv: {row.invoice}</span>
                                    </button>
                                    {isSent && <Send size={14} className="text-[#6bbdb7] shrink-0" />}
                                </div>
                                <div className="flex items-center gap-2 flex-wrap">
                                    <span className="text-[10px] font-black text-[#303a7f]">{row.horas.toFixed(1)}H</span>
                                    <span className="text-[10px] text-gray-300">|</span>
                                    <span className="text-[10px] font-black text-[#303a7f]">KBS: {formatCurrency(row.facturacion)}</span>
                                    <span className="text-[10px] font-bold text-red-400">LGM: {formatCurrency(row.costos)}</span>
                                    <span className="text-[10px] text-gray-300">|</span>
                                    <span className={`text-[10px] font-black ${row.utilidad >= 0 ? 'text-teal-600' : 'text-red-500'}`}>
                                        Util: {formatCurrency(row.utilidad)}
                                    </span>
                                </div>
                                <div className="flex items-center gap-1.5 flex-wrap text-[10px]">
                                    <span className="font-black text-[#303a7f]">Pago: {formatCurrencyInput(row.pago) || '$0.00'}</span>
                                    <span className="text-gray-300">|</span>
                                    <span className="font-bold text-gray-400 uppercase">FP: {row.fecha_pago || '--/--/--'}</span>
                                    <span className="text-gray-300">|</span>
                                    <span className={`font-black ${row.wos ? 'text-orange-500' : 'text-gray-300'}`}>WOS: {row.wos || '---'}</span>
                                </div>
                                <label className="flex items-center gap-1.5 cursor-pointer">
                                    <span className="text-[9px] font-black text-gray-400 uppercase">Pagado</span>
                                    <input
                                        type="checkbox"
                                        checked={row.pagada}
                                        onChange={(e) => onUpdateManualPE(row.correlativo, 'pagada', e.target.checked)}
                                        className="w-4 h-4 rounded border-gray-300 text-[#6bbdb7] focus:ring-[#59aba5] cursor-pointer accent-[#6bbdb7] transition-all"
                                    />
                                </label>
                            </div>
                        );
                    })}
                </div>

                {/* Resumen P.E */}
                <div className="px-6 py-10 border-y border-gray-50 flex items-center justify-between bg-gray-50/30 mb-20">
                    <div className="flex gap-12">
                        <div className="flex flex-col"><span className="text-[10px] font-black text-gray-400 uppercase mb-1">Total P.E Facturado</span><span className="text-xl font-black text-[#303a7f]">{formatCurrency(peTableData.reduce((acc, r) => acc + r.facturacion, 0))}</span></div>
                        <div className="flex flex-col"><span className="text-[10px] font-black text-gray-400 uppercase mb-1">Costo Proyectos</span><span className="text-xl font-black text-red-400">{formatCurrency(peTableData.reduce((acc, r) => acc + r.costos, 0))}</span></div>
                        <div className="flex flex-col border-l-2 border-gray-200 pl-12"><span className="text-[10px] font-black text-gray-400 uppercase mb-1">Utilidad P.E</span><span className="text-xl font-black text-[#6bbdb7]">{formatCurrency(peTableData.reduce((acc, r) => acc + r.utilidad, 0))}</span></div>
                    </div>
                </div>

            </div>
        </div>
    );
};

// ─── MÓDULO LGM: NÓMINA ADMINISTRATIVA ───────────────────────────────────────
// ─── AdminEmployeeAddView: Pantalla para agregar/editar personal Administrativo ─────────
const AdminEmployeeAddView = ({ employee, onSave, onDelete, onBack }) => {
    const isEdit = !!employee;
    const [showDeleteModal, setShowDeleteModal] = useState(false);
    const [confirmName, setConfirmName] = useState('');
    const [newEmp, setNewEmp] = useState(employee || {
        nombre: '',
        first_name: '',
        last_name: '',
        codigo_empleado: '',
        cargo: '',
        salario_quincenal: '',
        frecuencia_pago: 'Quincenal',
        metodo_pago: 'Direct Deposit',
        cuenta_bancaria: '',
        email: '',
        fecha_ingreso: new Date().toISOString().split('T')[0],
        tin: '',
        tin_type: 'SSN',
        address_1: '',
        city: '',
        state: '',
        zip: '',
        imagen: '',
        activo: true
    });

    const updateField = (field, value) => {
        setNewEmp(prev => {
            const updated = { ...prev, [field]: value };
            if (field === 'first_name' || field === 'last_name') {
                updated.nombre = `${updated.first_name} ${updated.last_name}`.trim();
            }
            return updated;
        });
    };

    const handleImageChange = (e) => {
        const file = e.target.files[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = function(ev) {
            const dataUrl = ev.target.result;
            updateField('imagen', dataUrl);
        };
        reader.readAsDataURL(file);
    };

    const handleSave = () => {
        if (!newEmp.first_name || !newEmp.last_name || !newEmp.codigo_empleado) {
            alert('Por favor complete los campos obligatorios: Nombre, Apellido e Identificador.');
            return;
        }
        if (!/^\d{4}$/.test(newEmp.codigo_empleado)) {
            alert('El Código de Empleado debe ser exactamente 4 dígitos numéricos.');
            return;
        }
        onSave(newEmp);
    };

    const inputCls = "w-full bg-gray-50 border-2 border-[#303a7f]/10 rounded-xl p-3.5 outline-none focus:border-[#303a7f]/30 focus:bg-white transition-all font-bold text-sm text-[#333333]";
    const labelCls = "text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-2 ml-1";

    return (
        <div className="fixed inset-0 z-[1000] bg-white flex flex-col animate-in slide-in-from-right duration-500">
            {/* Header */}
            <div className="bg-white border-b-2 border-gray-100 px-4 py-4 flex items-center gap-3 shadow-sm flex-shrink-0">
                <button
                    onClick={onBack}
                    className="flex items-center gap-1 px-2.5 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest active:scale-95 transition-all flex-shrink-0 btn-close-danger"
                >
                    <ArrowLeft size={14} />
                    Atrás
                </button>
                <div className="flex-1" />
                <div className="flex items-center gap-2 flex-shrink-0">
                    {isEdit && onDelete && (
                        <button onClick={() => setShowDeleteModal(true)} className="px-3 py-2.5 text-red-500 font-black text-[9px] uppercase tracking-widest active:bg-red-50 rounded-xl transition-all">Eliminar</button>
                    )}
                    <button onClick={handleSave} className="px-4 py-2.5 bg-[#303a7f] text-white rounded-xl font-black text-[9px] uppercase tracking-widest active:bg-[#252a5e] shadow-lg shadow-blue-900/20 transition-all">{isEdit ? 'Guardar' : 'Registrar'}</button>
                </div>
            </div>

            <div className="flex-1 overflow-y-auto bg-[#fcfcfd] p-4">
                <div className="max-w-lg mx-auto space-y-5">
                    {/* Photo & ID Section */}
                    <section className="bg-white rounded-2xl p-5 shadow-sm border border-gray-50 flex flex-col items-center">
                        <div className="relative">
                            <div className="w-32 h-32 rounded-2xl bg-gray-50 border-2 border-dashed border-gray-200 flex items-center justify-center overflow-hidden">
                                {newEmp.imagen ? (
                                    <img src={newEmp.imagen} className="w-full h-full object-cover" />
                                ) : (
                                    <div className="text-center">
                                        <Users size={28} className="text-gray-300 mx-auto" />
                                        <p className="text-[8px] font-black text-gray-400 uppercase tracking-wider mt-1">Foto</p>
                                    </div>
                                )}
                                <input type="file" accept="image/*" onChange={handleImageChange} className="absolute inset-0 opacity-0 cursor-pointer" />
                            </div>
                            <div className="absolute -bottom-1.5 -right-1.5 bg-[#6bbdb7] text-white p-2 rounded-xl shadow-md border-2 border-white">
                                <Settings size={14} />
                            </div>
                        </div>
                        <div className="mt-4 w-full space-y-3">
                            <div>
                                <label className={labelCls}>Identificador (SSN/ITIN/ID)</label>
                                <input type="text" placeholder="Ej: 0123" value={newEmp.codigo_empleado} onChange={(e) => updateField('codigo_empleado', e.target.value)} className={inputCls} maxLength={4} pattern="\d{4}" inputMode="numeric" />
                            </div>
                            <div>
                                <label className={labelCls}>Cargo Administrativo</label>
                                <input type="text" placeholder="Ej: Administrador" value={newEmp.cargo} onChange={(e) => updateField('cargo', e.target.value)} className={inputCls} />
                            </div>
                        </div>
                    </section>

                    {/* Salary & Payroll Section */}
                    <section className="bg-white rounded-2xl p-5 shadow-sm border border-[#6bbdb7]/10">
                        <h3 className="text-sm font-black text-[#6bbdb7] tracking-tighter mb-4 flex items-center gap-2">
                            <div className="bg-[#6bbdb7] p-1.5 rounded-lg"><DollarSign className="text-white" size={14} /></div>
                            Salario y Nómina
                        </h3>
                        <div className="space-y-4">
                            <div className="bg-[#303a7f]/5 rounded-xl p-4 border border-[#303a7f]/10">
                                <span className="text-[10px] font-black text-[#303a7f] uppercase tracking-widest block mb-3">Salario Base ({newEmp.frecuencia_pago})</span>
                                <div className="flex items-center bg-white border border-[#303a7f]/20 rounded-xl px-4 py-3 shadow-sm">
                                    <span className="text-[#303a7f] font-black mr-2 text-base">$</span>
                                    <input type="number" step="0.01" placeholder="0.00" value={newEmp.salario_quincenal} onChange={(e) => updateField('salario_quincenal', e.target.value)} className="w-full bg-transparent font-black text-[#303a7f] outline-none text-base" />
                                </div>
                            </div>
                            <div>
                                <label className={labelCls}>Frecuencia de Pago</label>
                                <select value={newEmp.frecuencia_pago} onChange={(e) => updateField('frecuencia_pago', e.target.value)} className={inputCls}>
                                    <option value="Quincenal">Quincenal</option>
                                    <option value="Mensual">Mensual</option>
                                </select>
                            </div>
                            <div>
                                <label className={labelCls}>Método de Pago</label>
                                <select value={newEmp.metodo_pago} onChange={(e) => updateField('metodo_pago', e.target.value)} className={inputCls}>
                                    <option value="Direct Deposit">Depósito Directo</option>
                                    <option value="Check">Cheque</option>
                                    <option value="Zelle">Zelle</option>
                                    <option value="Cash">Efectivo</option>
                                </select>
                            </div>
                        </div>
                    </section>

                    {/* Personal & Tax Info */}
                    <section className="bg-white rounded-2xl p-5 shadow-sm border border-gray-50">
                        <h3 className="text-sm font-black text-[#333333] tracking-tighter mb-4 flex items-center gap-2">
                            <div className="bg-[#303a7f] p-1.5 rounded-lg"><Users className="text-white" size={14} /></div>
                            Información Personal y Fiscal
                        </h3>
                        <div className="space-y-3">
                            <div>
                                <label className={labelCls}>Nombre(s)</label>
                                <input type="text" placeholder="Ej: Mariana" value={newEmp.first_name} onChange={(e) => updateField('first_name', e.target.value)} className={inputCls} />
                            </div>
                            <div>
                                <label className={labelCls}>Apellido(s)</label>
                                <input type="text" placeholder="Ej: Pepper" value={newEmp.last_name} onChange={(e) => updateField('last_name', e.target.value)} className={inputCls} />
                            </div>
                            <div>
                                <label className={labelCls}>Email de Contacto</label>
                                <input type="email" placeholder="email@ejemplo.com" value={newEmp.email} onChange={(e) => updateField('email', e.target.value)} className={inputCls} />
                            </div>
                            <div>
                                <label className={labelCls}>Tipo de Tax ID</label>
                                <select value={newEmp.tin_type} onChange={(e) => updateField('tin_type', e.target.value)} className={inputCls}>
                                    <option value="SSN">SSN</option>
                                    <option value="ITIN">ITIN</option>
                                    <option value="EIN">EIN</option>
                                </select>
                            </div>
                            <div>
                                <label className={labelCls}>Dirección</label>
                                <input type="text" placeholder="Calle, Número, Apto..." value={newEmp.address_1} onChange={(e) => updateField('address_1', e.target.value)} className={inputCls} />
                            </div>
                            <div className="grid grid-cols-3 gap-3">
                                <div>
                                    <label className={labelCls}>Ciudad</label>
                                    <input type="text" placeholder="Orlando" value={newEmp.city} onChange={(e) => updateField('city', e.target.value)} className={inputCls} />
                                </div>
                                <div>
                                    <label className={labelCls}>Estado</label>
                                    <input type="text" placeholder="FL" value={newEmp.state} onChange={(e) => updateField('state', e.target.value)} className={inputCls} />
                                </div>
                                <div>
                                    <label className={labelCls}>ZIP</label>
                                    <input type="text" placeholder="32803" value={newEmp.zip} onChange={(e) => updateField('zip', e.target.value)} className={inputCls} />
                                </div>
                            </div>
                        </div>
                    </section>

                    {/* Banking Info */}
                    <section className="bg-white rounded-2xl p-5 shadow-sm border border-gray-50">
                        <h3 className="text-sm font-black text-[#333333] tracking-tighter mb-4 flex items-center gap-2">
                            <div className="bg-gray-100 p-1.5 rounded-lg"><CreditCard className="text-[#303a7f]" size={14} /></div>
                            Información Bancaria
                        </h3>
                        <div>
                            <label className={labelCls}>Detalles de Cuenta</label>
                            <textarea rows={3} placeholder="Número de cuenta, Routing, Banco..." value={newEmp.cuenta_bancaria} onChange={(e) => updateField('cuenta_bancaria', e.target.value)} className={inputCls + " resize-none"}></textarea>
                        </div>
                    </section>
                </div>
            </div>

            {showDeleteModal && (
                <div className="fixed inset-0 z-[1001] flex items-center justify-center p-4">
                    <div className="absolute inset-0 bg-[#303a7f]/20 backdrop-blur-sm" onClick={() => setShowDeleteModal(false)} />
                    <div className="relative w-full max-w-md bg-white rounded-[2.5rem] p-10 shadow-2xl border-2 border-white animate-in zoom-in-95 duration-200">
                        <div className="flex flex-col items-center text-center">
                            <div className="w-20 h-20 bg-red-50 rounded-3xl flex items-center justify-center mb-6 text-red-500"><Trash2 size={36} /></div>
                            <h3 className="text-2xl font-black text-[#303a7f] tracking-tighter mb-3 uppercase">¿Eliminar empleado?</h3>
                            <p className="text-gray-400 text-xs mb-8">Escriba el nombre para confirmar: <br /><span className="font-black text-[#333333]">"{newEmp.nombre}"</span></p>
                            <input
                                type="text"
                                value={confirmName}
                                onChange={(e) => setConfirmName(e.target.value)}
                                className="w-full bg-gray-50 border-2 border-[#303a7f]/20 rounded-2xl p-4 outline-none text-center text-[#333333] font-bold focus:border-red-500/50 focus:bg-white transition-all"
                            />
                            <div className="flex gap-3 pt-6 w-full">
                                <button onClick={() => setShowDeleteModal(false)} className="flex-1 btn-close-danger font-black py-4 rounded-2xl transition-all">Cancelar</button>
                                <button
                                    disabled={confirmName !== newEmp.nombre}
                                    onClick={() => { setShowDeleteModal(false); onDelete(newEmp); }}
                                    className={`flex-1 font-black py-4 rounded-2xl text-white transition-all ${confirmName === newEmp.nombre ? 'bg-red-500 hover:bg-red-600 shadow-lg shadow-red-500/30' : 'bg-gray-100 text-gray-300'}`}
                                >
                                    Eliminar
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

const AdminPayrollView = ({
    adminEmployees = [],
    adminPayrollHistory = [],
    setAdminPayrollHistory,
    searchTerm = '',
    setSearchTerm,
    syncToDatabase,
    apiUrl,
    onRefresh,
    onAddEmployee,
    onDeleteEmployee,
    adminExpenses = [],
    setAdminExpenses,
    onRefreshExpenses
}) => {
    const [activeSection, setActiveSection] = useState('employees'); // 'employees' | 'payroll' | 'history' | 'expenses'
    const [selectedPeriod, setSelectedPeriod] = useState('');
    const [payrollRows, setPayrollRows] = useState([]);
    const [isConfirming, setIsConfirming] = useState(false);
    const [notif, setNotif] = useState({ open: false, type: 'success', msg: '' });
    const [isSendingEmail, setIsSendingEmail] = useState(false);
    const [isAddingAdminEmployee, setIsAddingAdminEmployee] = useState(false);
    const [editingAdminEmployee, setEditingAdminEmployee] = useState(null);
    const [isAddingExpense, setIsAddingExpense] = useState(false);

    // Cargar empleados automáticamente al cambiar el período
    useEffect(() => {
        if (selectedPeriod) {
            const activeEmps = adminEmployees.filter(e => e.activo);
            const rows = activeEmps.map(emp => ({
                id: emp.codigo_empleado || emp.nombre,
                nombre: emp.nombre,
                cargo: emp.cargo,
                email: emp.email,
                metodo_pago: emp.metodo_pago,
                cuenta_bancaria: emp.cuenta_bancaria,
                salario_base: emp.salario_quincenal,
                ajuste: 0,
                total: emp.salario_quincenal,
                pagado: false
            }));
            setPayrollRows(rows);
        } else {
            setPayrollRows([]);
        }
    }, [selectedPeriod, adminEmployees]);

    // Formatear moneda
    const fmtCurrency = (val) => {
        const n = parseFloat(val) || 0;
        return n.toLocaleString('en-US', { style: 'currency', currency: 'USD' });
    };

    // Generar opciones de quincenas (bisemanas de 14 días) desde el 28 de Diciembre 2025
    const generateBiweeklyOptions = () => {
        const options = [];
        const startDate = new Date(2025, 11, 28); // 28 de Dic 2025 (Mes 11)
        const now = new Date();

        const MS_PER_DAY = 24 * 60 * 60 * 1000;
        const MS_PER_BIWEEK = 14 * MS_PER_DAY;

        // Calculamos cuántas bisemanas han pasado desde el inicio
        const diffMS = now.getTime() - startDate.getTime();
        const currentBiweekIndex = Math.floor(diffMS / MS_PER_BIWEEK);

        // Generamos las últimas 12 bisemanas (desde la actual hacia atrás)
        for (let i = 0; i < 12; i++) {
            const idx = currentBiweekIndex - i;
            if (idx < 0) break;

            const pStart = new Date(startDate.getTime() + idx * MS_PER_BIWEEK);
            const pEnd = new Date(pStart.getTime() + 13 * MS_PER_DAY);

            const fmt = (d) => {
                const m = String(d.getMonth() + 1).padStart(2, '0');
                const day = String(d.getDate()).padStart(2, '0');
                return `${m}/${day}/${d.getFullYear()}`;
            };

            options.push(`${fmt(pStart)} — ${fmt(pEnd)}`);
        }
        return options;
    };

    // Cargar empleados en la tabla de pago al seleccionar período
    const handleLoadPayroll = () => {
        if (!selectedPeriod) return;
        const activeEmps = adminEmployees.filter(e => e.activo);
        const rows = activeEmps.map(emp => ({
            id: emp.codigo_empleado || emp.nombre,
            nombre: emp.nombre,
            cargo: emp.cargo,
            email: emp.email,
            metodo_pago: emp.metodo_pago,
            cuenta_bancaria: emp.cuenta_bancaria,
            salario_base: emp.salario_quincenal,
            ajuste: 0,
            total: emp.salario_quincenal,
            pagado: false
        }));
        setPayrollRows(rows);
        setActiveSection('payroll');
    };

    const updateRow = (id, field, val) => {
        setPayrollRows(prev => prev.map(r => {
            if (r.id !== id) return r;
            const updated = { ...r, [field]: val };
            updated.total = (parseFloat(updated.salario_base) || 0) + (parseFloat(updated.ajuste) || 0);
            return updated;
        }));
    };

    const removeRow = (id) => {
        setPayrollRows(prev => prev.filter(r => r.id !== id));
    };

    const showNotif = (type, msg) => {
        setNotif({ open: true, type, msg });
        setTimeout(() => setNotif({ open: false, type: 'success', msg: '' }), 4000);
    };

    const handleConfirmPayroll = async () => {
        if (!selectedPeriod || payrollRows.length === 0) return;
        setIsConfirming(true);
        try {
            const timestamp = new Date().toLocaleString();
            const newRecord = {
                periodo: selectedPeriod,
                fecha_confirmacion: timestamp,
                empleados: payrollRows.map(r => ({
                    nombre: r.nombre,
                    cargo: r.cargo,
                    salario_base: r.salario_base,
                    ajuste: r.ajuste,
                    total: r.total,
                    metodo_pago: r.metodo_pago
                })),
                total_nomina: payrollRows.reduce((acc, r) => acc + (r.total || 0), 0)
            };

            // Guardar en historial local
            setAdminPayrollHistory(prev => [newRecord, ...prev]);

            // Sincronizar a Sheets
            await syncToDatabase('upsert', {
                Periodo: selectedPeriod,
                Fecha_Confirmacion: timestamp,
                Total_Nomina: newRecord.total_nomina,
                Empleados_JSON: JSON.stringify(newRecord.empleados)
            }, 'Admin_Nomina_Historico', true);

            showNotif('success', `Nómina del período ${selectedPeriod} confirmada exitosamente.`);
            setActiveSection('history');
        } catch (e) {
            console.error('[LGM] Error confirmando nómina admin:', e);
            showNotif('error', 'Error al confirmar la nómina. Verifique la conexión.');
        } finally {
            setIsConfirming(false);
        }
    };

    const filteredEmployees = adminEmployees.filter(e =>
        e.nombre.toLowerCase().includes(searchTerm.toLowerCase()) ||
        e.cargo.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const totalNomina = payrollRows.reduce((acc, r) => acc + (parseFloat(r.total) || 0), 0);
    const isAlreadyConfirmed = adminPayrollHistory.some(record => record.periodo === selectedPeriod);

    return (
        <div className="w-full animate-in fade-in slide-in-from-bottom-4 duration-500">

            {/* Notificación flotante */}
            {notif.open && (
                <div className={`fixed top-24 right-6 z-[500] px-6 py-4 rounded-2xl shadow-2xl font-black text-sm uppercase tracking-widest animate-in fade-in zoom-in duration-300 ${notif.type === 'success' ? 'bg-[#6bbdb7] text-white' : 'bg-red-500 text-white'}`}>
                    {notif.msg}
                </div>
            )}

            {/* Header / Tabs & Actions Row */}
            <div className="flex flex-col gap-4 mb-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
                {/* Navigation Tabs */}
                <div className="bg-white rounded-2xl border-2 border-gray-100 p-1 flex flex-wrap gap-1 shadow-sm">
                    {[
                        { id: 'employees', label: 'Equipo', icon: Users },
                        { id: 'payroll', label: 'Pago', icon: CreditCard },
                        { id: 'history', label: 'Historial', icon: History },
                        { id: 'expenses', label: 'Gastos', icon: Receipt }
                    ].map(tab => (
                        <button
                            key={tab.id}
                            onClick={() => setActiveSection(tab.id)}
                            className={`flex-1 min-w-[calc(50%-0.25rem)] flex items-center justify-center gap-1.5 px-2 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${activeSection === tab.id ? 'bg-[#303a7f] text-white shadow-lg shadow-blue-900/10' : 'text-gray-400 active:bg-gray-50'}`}
                        >
                            <tab.icon size={12} />
                            {tab.label}
                        </button>
                    ))}
                </div>

                {/* Action Buttons */}
                {activeSection === 'employees' && (
                <button
                    onClick={() => setIsAddingAdminEmployee(true)}
                    className="flex items-center justify-center gap-2 px-4 py-3.5 bg-[#303a7f] text-white rounded-2xl font-black transition-all active:scale-95 shadow-xl shadow-blue-900/20 active:bg-[#252a5e]"
                >
                    <Plus size={18} />
                    <span className="tracking-widest uppercase text-[10px]">Agregar Personal</span>
                </button>
                )}
                {activeSection === 'expenses' && (
                <button
                    onClick={() => setIsAddingExpense(true)}
                    className="flex items-center justify-center gap-2 px-4 py-3.5 bg-[#303a7f] text-white rounded-2xl font-black transition-all active:scale-95 shadow-xl shadow-blue-900/20 active:bg-[#252a5e]"
                >
                    <Plus size={18} />
                    <span className="tracking-widest uppercase text-[10px]">Nuevo Gasto</span>
                </button>
                )}
            </div>

            {isAddingAdminEmployee && (
                <AdminEmployeeAddView
                    onBack={() => setIsAddingAdminEmployee(false)}
                    onSave={async (newEmp) => {
                        await onAddEmployee(newEmp);
                        setIsAddingAdminEmployee(false);
                    }}
                />
            )}

            {editingAdminEmployee && (
                <AdminEmployeeAddView
                    employee={editingAdminEmployee}
                    onBack={() => setEditingAdminEmployee(null)}
                    onSave={async (updatedEmp) => {
                        await onAddEmployee(updatedEmp);
                        setEditingAdminEmployee(null);
                    }}
                    onDelete={async (emp) => {
                        if (onDeleteEmployee) await onDeleteEmployee(emp);
                        setEditingAdminEmployee(null);
                    }}
                />
            )}

            {/* ── SECCIÓN: EQUIPO ── */}
            {activeSection === 'employees' && (
                <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                    {filteredEmployees.length === 0 ? (
                        <div className="py-32 text-center bg-white rounded-[2rem] border-2 border-dashed border-gray-100">
                            <Target size={48} className="text-gray-100 mx-auto mb-6" />
                            <p className="text-gray-400 font-black text-base uppercase tracking-[0.2em] opacity-50">
                                {adminEmployees.length === 0 ? 'No hay registros disponibles' : 'Sin coincidencias'}
                            </p>
                        </div>
                    ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                            {filteredEmployees.map((emp, i) => (
                                <div key={i} onClick={() => setEditingAdminEmployee(emp)} className="bg-white rounded-[2rem] border-2 border-gray-50 shadow-sm hover:shadow-xl hover:border-[#303a7f]/10 transition-all duration-500 overflow-hidden group cursor-pointer">
                                    {/* Header de la card */}
                                    <div className="bg-gradient-to-br from-[#303a7f] to-[#1e234d] p-6 relative">
                                        <div className="w-14 h-14 rounded-2xl bg-white/20 flex items-center justify-center text-white font-black text-2xl shadow-inner mb-3 overflow-hidden">
                                            {emp.imagen ? (
                                                <img src={emp.imagen} alt={emp.nombre} className="w-full h-full object-cover" />
                                            ) : (
                                                emp.nombre.charAt(0).toUpperCase()
                                            )}
                                        </div>
                                        <h3 className="text-sm font-black text-white uppercase tracking-tight leading-tight">{emp.nombre}</h3>
                                        <p className="text-[#6bbdb7] text-[10px] font-black uppercase tracking-widest mt-0.5">{emp.cargo}</p>
                                        <div className={`absolute top-4 right-4 px-2 py-0.5 rounded-full text-[8px] font-black uppercase tracking-widest ${emp.activo ? 'bg-green-400/20 text-green-200 border border-green-400/30' : 'bg-red-400/20 text-red-200 border border-red-400/30'}`}>
                                            {emp.activo ? 'Activo' : 'Inactivo'}
                                        </div>
                                    </div>

                                    {/* Datos */}
                                    <div className="p-5 space-y-3">
                                        <div className="flex items-center justify-between">
                                            <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Sueldo ({emp.frecuencia_pago || 'Quincenal'})</span>
                                            <span className="text-sm font-black text-[#303a7f]">{fmtCurrency(emp.salario_quincenal)}</span>
                                        </div>
                                        <div className="flex items-center justify-between">
                                            <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Método</span>
                                            <span className="text-[10px] font-black text-[#6bbdb7] uppercase">{emp.metodo_pago || '—'}</span>
                                        </div>
                                        {emp.email && (
                                            <div className="flex items-center gap-2 pt-1 border-t border-gray-50">
                                                <Mail size={12} className="text-gray-300 flex-shrink-0" />
                                                <span className="text-[9px] font-bold text-gray-400 truncate">{emp.email}</span>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            )}

            {/* ── SECCIÓN: MOTOR DE PAGO ── */}
            {activeSection === 'payroll' && (
                <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                    {/* Selector de período */}
                    <div className="bg-white rounded-[2rem] border-2 border-gray-50 shadow-sm p-6 mb-6">
                        <div className="w-full">
                            <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest block mb-2">Período Bisemanal</label>
                            <select
                                value={selectedPeriod}
                                onChange={e => setSelectedPeriod(e.target.value)}
                                className="w-full bg-gray-50 border-2 border-transparent text-[#303a7f] font-black rounded-2xl px-4 py-3 outline-none focus:border-[#303a7f]/10 text-xs transition-all"
                            >
                                <option value="">— Seleccionar Bisemana —</option>
                                {generateBiweeklyOptions().map((opt, i) => (
                                    <option key={i} value={opt}>{opt}</option>
                                ))}
                            </select>
                        </div>
                    </div>

                    {payrollRows.length === 0 ? (
                        <div className="py-24 text-center bg-white rounded-[2rem] border-2 border-dashed border-gray-100">
                            <CreditCard size={40} className="text-gray-100 mx-auto mb-4" />
                            <p className="text-gray-300 font-black text-xs uppercase tracking-widest">Seleccione un período para cargar el equipo automáticamente</p>
                        </div>
                    ) : (
                        <>
                            {/* Tabla nómina — estilo cards para móvil */}
                            <div className="space-y-3 mb-6">
                                {payrollRows.map((row) => (
                                    <div key={row.id} className="bg-white rounded-2xl border-2 border-gray-50 shadow-sm overflow-hidden">
                                        <div className="px-4 py-3 border-b border-gray-50 flex items-center justify-between bg-gray-50/30">
                                            <div className="min-w-0 flex-1">
                                                <p className="text-xs font-black text-[#303a7f] uppercase truncate">{row.nombre}</p>
                                                <p className="text-[9px] font-bold text-[#6bbdb7] uppercase tracking-wider truncate">{row.cargo}</p>
                                            </div>
                                            <button onClick={() => removeRow(row.id)} className="p-2 ml-2 text-gray-300 active:text-red-500 active:bg-red-50 rounded-xl transition-colors flex-shrink-0">
                                                <Trash2 size={16} />
                                            </button>
                                        </div>
                                        <div className="px-4 py-3 grid grid-cols-3 gap-3">
                                            <div>
                                                <span className="text-[8px] font-black text-gray-400 uppercase tracking-widest block mb-1">Sueldo Base</span>
                                                <span className="text-xs font-black text-[#303a7f]">{fmtCurrency(row.salario_base)}</span>
                                            </div>
                                            <div>
                                                <span className="text-[8px] font-black text-gray-400 uppercase tracking-widest block mb-1">Ajuste</span>
                                                <input
                                                    type="number"
                                                    value={row.ajuste}
                                                    onChange={e => updateRow(row.id, 'ajuste', e.target.value)}
                                                    className="w-full bg-gray-50 border border-gray-100 focus:border-[#303a7f]/20 text-[#303a7f] font-black rounded-lg px-2 py-1.5 outline-none text-xs text-right transition-all"
                                                    step="0.01"
                                                    placeholder="0.00"
                                                />
                                            </div>
                                            <div>
                                                <span className="text-[8px] font-black text-gray-400 uppercase tracking-widest block mb-1">Total</span>
                                                <span className="text-sm font-black text-[#6bbdb7]">{fmtCurrency(row.total)}</span>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>

                            {/* Footer de totales */}
                            <div className="bg-[#303a7f] rounded-2xl px-5 py-4 flex items-center justify-between mb-6">
                                <span className="text-[10px] font-black text-white/60 uppercase tracking-widest">Total Nómina</span>
                                <span className="text-xl font-black text-white tracking-tighter">{fmtCurrency(totalNomina)}</span>
                            </div>

                            {/* Botón confirmar */}
                            <div className="flex justify-end">
                                <button
                                    onClick={handleConfirmPayroll}
                                    disabled={isConfirming || isAlreadyConfirmed}
                                    className={`px-10 py-4 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all shadow-lg active:scale-95 flex items-center gap-3 ${isAlreadyConfirmed ? 'bg-emerald-500 cursor-not-allowed shadow-emerald-500/20' : 'bg-[#6bbdb7] hover:bg-[#59aba5] shadow-teal-900/10'} ${isConfirming ? 'opacity-60' : ''}`}
                                >
                                    {isConfirming ? <Loader2 size={16} className="animate-spin" /> : <CheckCircle size={16} />}
                                    {isConfirming ? 'Confirmando...' : (isAlreadyConfirmed ? 'Nómina Confirmada' : 'Confirmar Nómina')}
                                </button>
                            </div>
                        </>
                    )}
                </div>
            )}

            {/* ── SECCIÓN: HISTORIAL ── */}
            {activeSection === 'history' && (
                <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                    {adminPayrollHistory.length === 0 ? (
                        <div className="py-32 text-center bg-white rounded-[2rem] border-2 border-dashed border-gray-100">
                            <History size={48} className="text-gray-100 mx-auto mb-6" />
                            <p className="text-gray-400 font-black text-base uppercase tracking-[0.2em] opacity-50">Sin pagos confirmados aún</p>
                        </div>
                    ) : (
                        <div className="space-y-4">
                            {adminPayrollHistory.map((record, i) => (
                                <div key={i} className="bg-white rounded-[2rem] border-2 border-gray-50 shadow-sm overflow-hidden hover:shadow-lg transition-all duration-300">
                                    <div className="px-6 py-4 border-b-2 border-gray-50 flex items-center justify-between bg-gray-50/50">
                                        <div>
                                            <p className="text-xs font-black text-[#303a7f] uppercase tracking-tight">{record.periodo}</p>
                                            <p className="text-[9px] font-bold text-gray-400 mt-0.5">Confirmado: {record.fecha_confirmacion}</p>
                                        </div>
                                        <div className="text-right">
                                            <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Total Pagado</p>
                                            <p className="text-xl font-black text-[#6bbdb7]">{fmtCurrency(record.total_nomina)}</p>
                                        </div>
                                    </div>
                                    <div className="px-6 py-3 flex flex-wrap gap-3">
                                        {(record.empleados || []).map((emp, j) => (
                                            <div key={j} className="flex items-center gap-2 bg-gray-50 rounded-xl px-3 py-2">
                                                <div className="w-6 h-6 rounded-lg bg-[#303a7f]/10 flex items-center justify-center text-[#303a7f] font-black text-[9px]">{emp.nombre.charAt(0)}</div>
                                                <div>
                                                    <p className="text-[9px] font-black text-[#303a7f] uppercase leading-none">{emp.nombre}</p>
                                                    <p className="text-[8px] font-bold text-[#6bbdb7]">{fmtCurrency(emp.total)}</p>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            )}

            {/* ── SECCIÓN: GASTOS ── */}
            {activeSection === 'expenses' && (
                <AdminExpensesView
                    adminExpenses={adminExpenses}
                    setAdminExpenses={setAdminExpenses}
                    syncToDatabase={syncToDatabase}
                    apiUrl={apiUrl}
                    onRefresh={onRefreshExpenses}
                    openAdd={isAddingExpense}
                    setOpenAdd={setIsAddingExpense}
                />
            )}
        </div>
    );
};

