            "Correlativo": existing.correlativo || existing.Correlativo || '',
            "Fecha Rad.": existing['fecha rad.'] || existing['Fecha Rad.'] || '',
            "Pago": existing.pago || existing.Pago || '',
            "Fecha de Pago": existing['fecha de pago'] || existing['Fecha de Pago'] || '',
