                                                setBiometricTableData(payload.biometricTableData || []);
                                                setEarningsTableData(payload.earningsTableData || []);
                                                setKbsBillingTableData(payload.kbsBillingTableData || []);
                                                setRawBiometricData(payload.rawBiometricData || []);
